610	/** A plain right-facing chevron — the icon sprite sheet has no arrow/chevron
611	 *  mark, so the row-affordance and nav-row chevrons below are a raw inline
612	 *  SVG (the same escape hatch other Nexion components already use for this,
613	 *  e.g. ChatWidget's own back arrow), not a repurposed unrelated icon. */
614	function ChevronRight({ className = "" }: { className?: string }) {
615	  return (
616	    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"
617	         strokeLinecap="round" strokeLinejoin="round" className={"opacity-50 " + className} aria-hidden>
618	      <path d="M9 18l6-6-6-6" />
619	    </svg>
620	  );
621	}
622	
623	type TicketThreadMessage = TicketThread["messages"][number];
624	
625	/** A run of consecutive messages from the same author, close enough together
626	 *  in time to read as one turn of the conversation. This is what turns a
627	 *  multi-image send (one text message + N attachment-only follow-ups, see
628	 *  `replyTicket` in lib/actions-support.ts) back into a single bubble with an
629	 *  image grid, instead of a wall of near-identical empty bubbles. */
630	type MessageCluster = { authorId: string; isStaff: boolean; authorName: string; lastAt: string; messages: TicketThreadMessage[] };
631	
632	const CLUSTER_GAP_MS = 60_000;
633	
634	function clusterMessages(messages: TicketThreadMessage[]): MessageCluster[] {
635	  const clusters: MessageCluster[] = [];
636	  for (const m of messages) {
637	    const last = clusters[clusters.length - 1];
638	    const gap = last ? new Date(m.createdAt).getTime() - new Date(last.lastAt).getTime() : Infinity;
639	    if (last && last.authorId === m.authorId && last.isStaff === m.isStaff && gap <= CLUSTER_GAP_MS) {
640	      last.messages.push(m);
641	      last.lastAt = m.createdAt;
642	    } else {
643	      clusters.push({ authorId: m.authorId, isStaff: m.isStaff, authorName: m.authorName, lastAt: m.createdAt, messages: [m] });
644	    }
645	  }
646	  return clusters;
647	}
648	
649	function initialsOf(name: string): string {
650	  const parts = name.trim().split(/\s+/).filter(Boolean);
651	  if (parts.length === 0) return "?";
652	  return (parts[0][0] + (parts[1]?.[0] ?? "")).toUpperCase();
653	}
