655	function Avatar({ isStaff, name }: { isStaff: boolean; name: string }) {
656	  return (
657	    <span
658	      className={
659	        "grid h-6 w-6 flex-none place-items-center rounded-full text-[9.5px] font-bold " +
660	        (isStaff ? "bg-gradient-to-br from-accent-blue to-brand-500 text-white" : "border border-rim-hi bg-well text-tx-dim")
661	      }
662	      aria-hidden
663	    >
664	      {initialsOf(name)}
665	    </span>
666	  );
667	}
