/**
 * "Is typing" signal — deliberately in-memory, never persisted. Every real
 * chat product treats typing indicators as throwaway state (Slack, Discord,
 * iMessage never write one to a database); a DB round trip for something
 * that expires in 4 seconds would be pure churn. This assumes a single Node
 * process, which is what this app runs as — if that ever changes, this map
 * would need to move to a shared store, but it does not need to yet.
 */
const typingPings = new Map<string, { staffAt: number; customerAt: number }>();
const TYPING_TTL_MS = 4000;

function sweepTypingPings() {
  const cutoff = Date.now() - 5 * 60_000;
  for (const [id, v] of typingPings) {
    if (v.staffAt < cutoff && v.customerAt < cutoff) typingPings.delete(id);
  }
}

/** Called (throttled, client-side) on every keystroke in a ticket's reply box. */
export async function pingTyping(ticketId: string): Promise<void> {
  const user = await requireTicketActor();
  const ticket = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
  if (!ticket) return;
  if (ticket.userId !== user.id && !user.isSupportStaff) return;
  const isStaff = user.isSupportStaff && ticket.userId !== user.id;
  sweepTypingPings();
  const prev = typingPings.get(ticketId) ?? { staffAt: 0, customerAt: 0 };
  typingPings.set(ticketId, isStaff ? { ...prev, staffAt: Date.now() } : { ...prev, customerAt: Date.now() });
}

/** Whether the OTHER party (relative to whoever's asking) is typing right now. */
export async function getTypingStatus(ticketId: string): Promise<{ typing: boolean }> {
  const user = await requireTicketActor();
  const ticket = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
  if (!ticket) return { typing: false };
  if (ticket.userId !== user.id && !user.isSupportStaff) return { typing: false };
  const viewerIsStaff = user.isSupportStaff && ticket.userId !== user.id;
  const ping = typingPings.get(ticketId);
  if (!ping) return { typing: false };
  const at = viewerIsStaff ? ping.customerAt : ping.staffAt;
  return { typing: Date.now() - at < TYPING_TTL_MS };
