const TICKET_STATUS_CHOICES = ["OPEN", "CLOSED"] as const;
const TICKET_PRIORITY_CHOICES = ["LOW", "NORMAL", "HIGH", "URGENT"] as const;

export async function setTicketStatus(ticketId: string, status: "OPEN" | "CLOSED") {
  const user = await requireTicketActor();
  if (!TICKET_STATUS_CHOICES.includes(status as (typeof TICKET_STATUS_CHOICES)[number])) {
    throw new Error("A ticket can only be reopened or closed from here.");
  }
  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
  if (!ticket) throw new Error("Not found");
  if (ticket.userId !== user.id && !user.isSupportStaff) throw new Error("Forbidden");
  await db.ticket.update({ where: { id: ticketId }, data: { status } });
  // Best-effort, never blocks the status change itself.
  void setDiscordThreadArchived("ticket", (ticket as any).discordThreadId, status === "CLOSED");
  revalidatePath(`/dashboard/support`);
  revalidatePath(`/dashboard/support/${ticketId}`);
  revalidatePath(`/admin/support`);
  revalidatePath(`/admin/support/${ticketId}`);
}

export async function setTicketPriority(ticketId: string, priority: "LOW" | "NORMAL" | "HIGH" | "URGENT") {
  const user = await requireTicketActor();
  // Triage is a staff-only judgement — a customer must not be able to promote
  // their own ticket to URGENT — but it IS the support desk's job.
  if (!user.isSupportStaff) throw new Error("Forbidden");
  if (!TICKET_PRIORITY_CHOICES.includes(priority as (typeof TICKET_PRIORITY_CHOICES)[number])) {
    throw new Error("Priority must be one of: LOW, NORMAL, HIGH, URGENT.");
  }
  await db.ticket.update({ where: { id: ticketId }, data: { priority } });
  revalidatePath(`/admin/support`);
  revalidatePath(`/admin/support/${ticketId}`);
}

/** How long after sending a message its author may still edit it. */
const EDIT_WINDOW_MS = 5 * 60_000;

/**
 * Edit the body of your own message, within 5 minutes of sending it, while the
 * ticket is open. The 5-minute window is enforced HERE against `createdAt` —
 * never trust a client-side countdown, which only controls whether the "Edit"
 * affordance is shown. `editedAt` is set so both the admin and customer UI can
 * render an "(edited)" label — an edit is a transparency signal both parties
 * see, unlike the read receipts below which are staff-facing only.
 */
export async function editTicketMessage(messageId: string, newBody: string): Promise<{ error?: string }> {
  const user = await requireUser();
  const body = newBody.trim();
  if (body.length < 2 || body.length > 10000) return { error: "Message must be between 2 and 10,000 characters." };

  const message = await db.ticketMessage.findUnique({
    where: { id: messageId },
    include: { ticket: { select: { id: true, status: true } } },
  });
  if (!message) return { error: "Message not found." };
  if (message.authorId !== user.id) return { error: "You can only edit your own messages." };
  if (message.ticket.status === "CLOSED") return { error: "This ticket is closed." };
  if (Date.now() - message.createdAt.getTime() >= EDIT_WINDOW_MS) {
    return { error: "You can only edit a message within 5 minutes of sending it." };
  }

  await db.ticketMessage.update({ where: { id: messageId }, data: { body, editedAt: new Date() } });
  revalidatePath(`/dashboard/support/${message.ticket.id}`);
  revalidatePath(`/admin/support/${message.ticket.id}`);
  return {};
}

