/* Shared vector-art primitives for the customer portal.
 *
 * WHY THIS FILE EXISTS. Several portal pages (SSL first; Support and Domains are
 * being overhauled in parallel) carried raster hero renders — e.g. the old
 * 900x600 `hero-ssl-shield.webp`, drawn at ~450px wide so it was at best 1x on
 * a retina screen, with its glow and palette baked into pixels that could not
 * follow light mode. Everything here is inline SVG that reads its colours from
 * the theme tokens (`--color-blue`, `--color-violet`, `--color-magenta`,
 * `--color-cyan`, `--color-surface`, `--color-rim-hi`…), so it is crisp at any
 * density and flips with the theme for free.
 *
 * Every <defs> id is namespaced by the caller's `uid`, because two SVGs on one
 * page that both define `id="grad"` silently share whichever was parsed first.
 *
 * Decorative only: callers wrap these in an `aria-hidden` container.
 */

export type VectorTone = "blue" | "violet" | "magenta" | "cyan" | "mint" | "amber" | "rose";

/** The CSS variable for a tone. */
export const toneVar = (t: VectorTone) => `var(--color-${t})`;

/** Brand ramp (blue → violet → magenta) + a soft halo, namespaced by `uid`. */
export function BrandDefs({ uid }: { uid: string }) {
  return (
    <defs>
      <linearGradient id={`${uid}-brand`} x1="0" y1="0" x2="1" y2="1">
        <stop offset="0%" style={{ stopColor: "var(--color-blue)" }} />
        <stop offset="55%" style={{ stopColor: "var(--color-violet)" }} />
        <stop offset="100%" style={{ stopColor: "var(--color-magenta)" }} />
      </linearGradient>
      <linearGradient id={`${uid}-brand-h`} x1="0" y1="0" x2="1" y2="0">
        <stop offset="0%" style={{ stopColor: "var(--color-cyan)", stopOpacity: 0 }} />
        <stop offset="30%" style={{ stopColor: "var(--color-blue)" }} />
        <stop offset="70%" style={{ stopColor: "var(--color-violet)" }} />
        <stop offset="100%" style={{ stopColor: "var(--color-magenta)", stopOpacity: 0 }} />
      </linearGradient>
      <linearGradient id={`${uid}-panel`} x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" style={{ stopColor: "var(--color-surface)" }} />
        <stop offset="100%" style={{ stopColor: "var(--color-well)" }} />
