/**
 * Support ticket intake — the pure (no DB, no server-only imports) half of the
 * customer "New ticket" flow on /dashboard/support.
 *
 * Why this exists: the old form asked for subject + priority + message and
 * nothing else, so the first staff reply on most tickets was "which server is
 * this about?". The new flow asks for a CATEGORY and (optionally) WHICH SERVICE,
 * and suggests help articles as the customer types.
 *
 * No schema change: category and service are written as a two-line header at
 * the top of the opening message (see `composeTicketBody`). Staff see it as
 * plain text in the admin desk, the Discord mirror and email notifications
 * without touching any of them, and the customer thread view parses it back
 * into chips (`parseTicketBodyHeader`). The header is only ever composed
 * server-side, from a category key validated against TICKET_CATEGORIES and a
 * service label resolved from a row the customer owns — never from free text.
 *
 * Imported by both the client form and `createTicket` (lib/actions-support.ts),
 * so it must stay free of server-only modules.
 */

export type TicketCategoryKey = "server" | "game" | "billing" | "domains" | "account" | "other";

export type TicketCategory = {
  key: TicketCategoryKey;
  label: string;
  /** Icon name from lib/nx/icon-paths.ts (vector set only). */
  icon: string;
  /** One short line under the label in the picker. */
  hint: string;
  /** Whether the "Which service?" picker is relevant for this category. */
  wantsService: boolean;
};

export const TICKET_CATEGORIES: readonly TicketCategory[] = [
  { key: "server", label: "Server & performance", icon: "server", hint: "VPS access, networking, speed", wantsService: true },
  { key: "game", label: "Game server", icon: "gamepad", hint: "Crashes, mods, versions, players", wantsService: true },
  { key: "billing", label: "Billing & invoices", icon: "card", hint: "Charges, renewals, refunds", wantsService: false },
  { key: "domains", label: "Domains, DNS & email", icon: "globe", hint: "Records, transfers, mailboxes", wantsService: true },
  { key: "account", label: "Account & security", icon: "shieldcheck", hint: "Login, 2FA, team access", wantsService: false },
  { key: "other", label: "Something else", icon: "chatdots", hint: "Questions, requests, feedback", wantsService: false },
] as const;

const CATEGORY_BY_KEY = new Map(TICKET_CATEGORIES.map((c) => [c.key, c]));

export function ticketCategory(key: string | null | undefined): TicketCategory | null {
  if (!key) return null;
  return CATEGORY_BY_KEY.get(key as TicketCategoryKey) ?? null;
}

/* ── Service reference ("which service is this about?") ──────────────────── */

export type ServiceKind = "server" | "hosting" | "domain";
export type ServiceRef = { kind: ServiceKind; id: string };

/** One option in the service picker. `value` is what the form submits. */
export type ServiceOption = { value: string; kind: ServiceKind; label: string; detail: string; game?: boolean };

const SERVICE_KINDS: readonly ServiceKind[] = ["server", "hosting", "domain"];

export function serviceValue(kind: ServiceKind, id: string): string {
  return `${kind}:${id}`;
}

/**
 * Parse the picker's submitted value. Anything that is not exactly
 * `<kind>:<id>` with a known kind and a cuid-ish id is rejected — this is a
 * network-submitted string, and the id is looked up (scoped to the caller)
 * afterwards, so the parse only has to be strict, not trusting.
 */
export function parseServiceRef(raw: unknown): ServiceRef | null {
  if (typeof raw !== "string") return null;
  const m = /^([a-z]+):([A-Za-z0-9_-]{6,64})$/.exec(raw.trim());
  if (!m) return null;
  const kind = m[1] as ServiceKind;
  if (!SERVICE_KINDS.includes(kind)) return null;
  return { kind, id: m[2] };
}

/* ── Opening-message header ─────────────────────────────────────────────── */

const CATEGORY_PREFIX = "Category: ";
const SERVICE_PREFIX = "Service: ";

/** Strip line breaks so a label can never inject a second header line. */
function oneLine(s: string): string {
  return s.replace(/[\r\n]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 160);
}

/**
 * The opening message as stored: an optional `Category:` / `Service:` header,
 * a blank line, then exactly what the customer typed. With neither, the body
 * is returned untouched, so a ticket opened from anywhere else is unchanged.
 */
export function composeTicketBody(args: { category?: TicketCategory | null; serviceLabel?: string | null; body: string }): string {
  const lines: string[] = [];
  if (args.category) lines.push(CATEGORY_PREFIX + args.category.label);
  if (args.serviceLabel && oneLine(args.serviceLabel)) lines.push(SERVICE_PREFIX + oneLine(args.serviceLabel));
  if (lines.length === 0) return args.body;
  return lines.join("\n") + "\n\n" + args.body;
}

/**
 * The inverse, for the thread view. Only a header that is EXACTLY what
 * `composeTicketBody` writes (known category label, header lines first,
 * followed by a blank line) is lifted out — a customer who happens to start a
 * message with "Category: …" in some other shape just sees their own text.
 */
export function parseTicketBodyHeader(body: string): { category: TicketCategory | null; service: string | null; rest: string } {
  const none = { category: null, service: null, rest: body };
  const split = body.indexOf("\n\n");
  if (split <= 0) return none;
  const head = body.slice(0, split).split("\n");
  if (head.length > 2) return none;
  let category: TicketCategory | null = null;
  let service: string | null = null;
  for (const line of head) {
    if (line.startsWith(CATEGORY_PREFIX) && !category && !service) {
      const label = line.slice(CATEGORY_PREFIX.length);
      category = TICKET_CATEGORIES.find((c) => c.label === label) ?? null;
      if (!category) return none;
    } else if (line.startsWith(SERVICE_PREFIX) && !service) {
      service = line.slice(SERVICE_PREFIX.length).trim() || null;
      if (!service) return none;
    } else {
      return none;
    }
  }
  return { category, service, rest: body.slice(split + 2) };
}

/* ── Suggested help articles ────────────────────────────────────────────── */

export type HelpArticleLite = { slug: string; title: string; category: string };

const STOPWORDS = new Set(
  ("a an and are as at be but by can cant could do does doesnt dont for from get got had has have help hi hello how i im " +
    "in into is it its just me my need not of on or our please since so some still that the their them then there this " +
    "to up us was we what when where which why will with wont would you your after before again any about").split(" "),
);

/** Lower-case word stems worth matching on (3+ chars, not a stopword). */
export function keywords(text: string): string[] {
  const out = new Set<string>();
  for (const raw of text.toLowerCase().normalize("NFKD").split(/[^a-z0-9]+/)) {
    if (raw.length < 3 || STOPWORDS.has(raw)) continue;
    // A deliberately crude stem: "crashes"/"crashing"/"crashed" → "crash".
    out.add(raw.replace(/(ing|ed|es|s)$/, "") || raw);
  }
  return [...out];
}

/** Help-center category names that line up with each ticket category. */
const CATEGORY_AFFINITY: Record<TicketCategoryKey, string[]> = {
  server: ["vps", "security", "tutorials", "control panels"],
  game: ["gaming"],
  billing: ["guides"],
  domains: ["domains", "hosting"],
  account: ["security"],
  other: [],
};

/**
 * Rank help articles against what the customer has typed so far. Pure and
 * cheap (a few hundred titles, run on keystroke), so it lives client-side.
 * An article must share at least one keyword with the text to be suggested;
 * the category only breaks ties — it never surfaces an unrelated article.
 */
export function suggestArticles(
  text: string,
  articles: readonly HelpArticleLite[],
  opts: { category?: TicketCategoryKey | null; limit?: number } = {},
): HelpArticleLite[] {
  const words = keywords(text);
  if (words.length === 0) return [];
  const affinity = new Set(opts.category ? CATEGORY_AFFINITY[opts.category] : []);
  const scored: { a: HelpArticleLite; score: number; i: number }[] = [];
  articles.forEach((a, i) => {
    const title = new Set(keywords(a.title));
    let hits = 0;
    for (const w of words) if (title.has(w)) hits++;
    if (hits === 0) return;
    const score = hits * 10 + (affinity.has(a.category.toLowerCase()) ? 3 : 0);
    scored.push({ a, score, i });
  });
  scored.sort((x, y) => y.score - x.score || x.i - y.i);
  return scored.slice(0, opts.limit ?? 4).map((s) => s.a);
}

/* ── Ticket list filters ───────────────────────────────────────────────── */

export type TicketFilterKey = "all" | "open" | "waiting" | "closed";

export const TICKET_FILTERS: readonly { key: TicketFilterKey; label: string }[] = [
  { key: "all", label: "All" },
  { key: "waiting", label: "Waiting for you" },
  { key: "open", label: "Open" },
  { key: "closed", label: "Closed" },
];

/** `open` = anything not closed; `waiting` = staff replied, customer's move. */
export function matchesTicketFilter(status: string, filter: TicketFilterKey): boolean {
  switch (filter) {
    case "open": return status !== "CLOSED";
    case "waiting": return status === "ANSWERED";
    case "closed": return status === "CLOSED";
    default: return true;
  }
}

export function ticketFilterCounts(statuses: readonly string[]): Record<TicketFilterKey, number> {
  const out: Record<TicketFilterKey, number> = { all: 0, open: 0, waiting: 0, closed: 0 };
  for (const s of statuses) for (const f of TICKET_FILTERS) if (matchesTicketFilter(s, f.key)) out[f.key]++;
  return out;
}

