  articles: readonly HelpArticleLite[],
  opts: { category?: TicketCategoryKey | null; limit?: number } = {},
): HelpArticleLite[] {
  const words = keywords(text);
  if (words.length === 0) return [];
  const affinity = new Set(opts.category ? CATEGORY_AFFINITY[opts.category] : []);
  const scored: { a: HelpArticleLite; score: number; i: number }[] = [];
  articles.forEach((a, i) => {
    const title = new Set(keywords(a.title));
    let hits = 0;
    for (const w of words) if (title.has(w)) hits++;
    if (hits === 0) return;
    const score = hits * 10 + (affinity.has(a.category.toLowerCase()) ? 3 : 0);
    scored.push({ a, score, i });
  });
  scored.sort((x, y) => y.score - x.score || x.i - y.i);
  return scored.slice(0, opts.limit ?? 4).map((s) => s.a);
}

/* ── Ticket list filters ───────────────────────────────────────────────── */

export type TicketFilterKey = "all" | "open" | "waiting" | "closed";

export const TICKET_FILTERS: readonly { key: TicketFilterKey; label: string }[] = [
  { key: "all", label: "All" },
  { key: "waiting", label: "Waiting for you" },
  { key: "open", label: "Open" },
  { key: "closed", label: "Closed" },
];

/** `open` = anything not closed; `waiting` = staff replied, customer's move. */
export function matchesTicketFilter(status: string, filter: TicketFilterKey): boolean {
  switch (filter) {
    case "open": return status !== "CLOSED";
    case "waiting": return status === "ANSWERED";
    case "closed": return status === "CLOSED";
    default: return true;
  }
}

export function ticketFilterCounts(statuses: readonly string[]): Record<TicketFilterKey, number> {
  const out: Record<TicketFilterKey, number> = { all: 0, open: 0, waiting: 0, closed: 0 };
  for (const s of statuses) for (const f of TICKET_FILTERS) if (matchesTicketFilter(s, f.key)) out[f.key]++;
  return out;
}

