import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import {
  TICKET_CATEGORIES,
  ticketCategory,
  parseServiceRef,
  serviceValue,
  composeTicketBody,
  parseTicketBodyHeader,
  keywords,
  suggestArticles,
  matchesTicketFilter,
  ticketFilterCounts,
} from "../lib/support-intake.ts";

const billing = ticketCategory("billing")!;

test("ticketCategory only resolves known keys", () => {
  assert.equal(ticketCategory("game")?.label, "Game server");
  assert.equal(ticketCategory("GAME"), null);
  assert.equal(ticketCategory("__proto__"), null);
  assert.equal(ticketCategory(""), null);
  assert.equal(ticketCategory(null), null);
  assert.equal(new Set(TICKET_CATEGORIES.map((c) => c.key)).size, TICKET_CATEGORIES.length);
});

test("parseServiceRef is strict about kind and id shape", () => {
  assert.deepEqual(parseServiceRef("server:cmuwz8cd10000hlme2o7wncxr"), { kind: "server", id: "cmuwz8cd10000hlme2o7wncxr" });
  assert.deepEqual(parseServiceRef(serviceValue("domain", "abc123def")), { kind: "domain", id: "abc123def" });
  for (const bad of ["", "server:", ":abc123", "vm:abc12345", "server:abc 123", "server:a", "server:abc123;drop", 42, null, undefined, { kind: "server" }]) {
    assert.equal(parseServiceRef(bad), null, `should reject ${JSON.stringify(bad)}`);
  }
});

test("composeTicketBody leaves a plain body untouched", () => {
  assert.equal(composeTicketBody({ body: "hello there" }), "hello there");
  assert.equal(composeTicketBody({ body: "x", serviceLabel: "   " }), "x");
});

test("compose → parse round-trips category and service", () => {
  const body = "SSH times out.\n\nSecond paragraph.";
  const composed = composeTicketBody({ category: billing, serviceLabel: "VPS · web-prod-01 · 203.0.113.24", body });
  assert.equal(composed, "Category: Billing & invoices\nService: VPS · web-prod-01 · 203.0.113.24\n\n" + body);
  const parsed = parseTicketBodyHeader(composed);
  assert.equal(parsed.category?.key, "billing");
  assert.equal(parsed.service, "VPS · web-prod-01 · 203.0.113.24");
  assert.equal(parsed.rest, body);

  const onlyCat = parseTicketBodyHeader(composeTicketBody({ category: billing, body: "b" }));
  assert.equal(onlyCat.category?.key, "billing");
  assert.equal(onlyCat.service, null);
  assert.equal(onlyCat.rest, "b");
});

test("a service label cannot smuggle in an extra header line", () => {
  const composed = composeTicketBody({ category: null, serviceLabel: "evil\nCategory: Billing & invoices", body: "b" });
  assert.equal(composed.split("\n\n")[0].split("\n").length, 1);
});

test("parseTicketBodyHeader ignores customer text that only looks like a header", () => {
  for (const body of [
    "Category: Not a real one\n\nbody",
    "Category: Billing & invoices\nsomething else\n\nbody",
    "Service: web-01\nCategory: Billing & invoices\n\nbody",
    "Category: Billing & invoices",
    "Hello\n\nCategory: Billing & invoices",
    "Service: \n\nbody",
  ]) {
    const p = parseTicketBodyHeader(body);
    assert.equal(p.rest, body, JSON.stringify(body));
    assert.equal(p.category, null);
    assert.equal(p.service, null);
  }
});

test("keywords drop stopwords and fold simple suffixes", () => {
  assert.deepEqual(keywords("My server keeps CRASHING after the plugin"), ["server", "keep", "crash", "plugin"]);
  assert.deepEqual(keywords("hi, can you help?"), []);
});

const ARTICLES = [
  { slug: "a", title: "Fixing a Minecraft server that crashes after adding a plugin", category: "Gaming" },
  { slug: "b", title: "SSH says 'connection timed out' — a checklist", category: "VPS" },
  { slug: "c", title: "Resetting your VPS root password", category: "VPS" },
  { slug: "d", title: "Pointing a domain at your server", category: "Domains" },
  { slug: "e", title: "Firewall basics for a new VPS", category: "Security" },
];

test("suggestArticles ranks by keyword overlap and needs at least one hit", () => {
  assert.deepEqual(suggestArticles("", ARTICLES), []);
  assert.deepEqual(suggestArticles("refund please", ARTICLES), []);
  assert.equal(suggestArticles("minecraft crashing with a new plugin", ARTICLES)[0].slug, "a");
  assert.equal(suggestArticles("ssh connection timed out", ARTICLES)[0].slug, "b");
  assert.equal(suggestArticles("vps", ARTICLES, { limit: 1 }).length, 1);
});

test("category only breaks ties, never surfaces an unrelated article", () => {
  // "server" matches a and d equally; the domains category pulls d first.
  assert.equal(suggestArticles("server", ARTICLES, { category: "domains" })[0].slug, "d");
  assert.equal(suggestArticles("server", ARTICLES, { category: "game" })[0].slug, "a");
  assert.ok(!suggestArticles("server", ARTICLES, { category: "domains" }).some((a) => a.slug === "c"));
});

test("ticket filters match the real TicketStatus values", () => {
  assert.ok(matchesTicketFilter("ANSWERED", "waiting"));
  assert.ok(!matchesTicketFilter("CUSTOMER_REPLY", "waiting"));
  assert.ok(matchesTicketFilter("CUSTOMER_REPLY", "open"));
  assert.ok(!matchesTicketFilter("CLOSED", "open"));
  assert.deepEqual(ticketFilterCounts(["OPEN", "ANSWERED", "CUSTOMER_REPLY", "CLOSED", "CLOSED"]), { all: 5, open: 3, waiting: 1, closed: 2 });
});

/* createTicket is a public POST endpoint: the service it attaches must be
   resolved through a query scoped to the caller, and attachments must go
   through the same byte validator replies use. */
test("createTicket scopes the service lookup to the caller and validates attachments", () => {
  const src = readFileSync(new URL("../lib/actions-support.ts", import.meta.url), "utf8");
  const start = src.indexOf("export async function createTicket(");
  const end = src.indexOf("\nexport ", start + 10);
  const body = src.slice(start, end);
  assert.ok(body.includes("resolveOwnedServiceLabel(user.id"), "service label must be resolved for the caller");
  assert.ok(body.includes("validateTicketAttachmentBytes"), "attachments must use the shared validator");
  assert.ok(body.indexOf("validateTicketAttachmentBytes") < body.indexOf("createTicketCore("), "files are validated before the ticket exists");
  const helper = src.slice(src.indexOf("async function resolveOwnedServiceLabel("));
  const helperBody = helper.slice(0, helper.indexOf("\n}\n"));
  assert.equal((helperBody.match(/userId/g) ?? []).length >= 4, true, "every service lookup is scoped by userId");
});

