 * The customer-facing label for a service picked in the New ticket form, or
 * null if the id is not one of THIS customer's own services. Every lookup is
 * scoped by `userId` — the value arrives from a POST body, so a guessed or
 * copied id belonging to someone else must resolve to nothing (and therefore
 * never leak another customer's hostname/IP into a ticket).
 */
async function resolveOwnedServiceLabel(userId: string, raw: unknown): Promise<string | null> {
  const ref = parseServiceRef(raw);
  if (!ref) return null;
  if (ref.kind === "server") {
    const s = await db.server.findFirst({
      where: { id: ref.id, userId },
      select: { hostname: true, label: true, name: true, ipAddress: true, gamePlanId: true },
    });
    if (!s) return null;
    const name = s.label || s.name || s.hostname;
    return [s.gamePlanId ? "Game server" : "Server", name === s.hostname ? name : `${name} (${s.hostname})`, s.ipAddress]
      .filter(Boolean).join(" · ");
  }
  if (ref.kind === "hosting") {
    const h = await db.hostingAccount.findFirst({ where: { id: ref.id, userId }, select: { primaryDomain: true } });
    return h ? `Web hosting · ${h.primaryDomain}` : null;
  }
  const d = await db.domain.findFirst({ where: { id: ref.id, userId }, select: { name: true } });
  return d ? `Domain · ${d.name}` : null;
}

export async function createTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireUser();
  const parsed = z
    .object({
      subject: z.string().min(3).max(150),
      body: z.string().min(5).max(10000),
      priority: z.enum(["LOW", "NORMAL", "HIGH", "URGENT"]).default("NORMAL"),
    })
    .safeParse({
      subject: formData.get("subject"),
      body: formData.get("body"),
      priority: formData.get("priority") ?? "NORMAL",
    });
  if (!parsed.success) return { error: "Subject (3+) and message (5+) required." };

  // Optional context from the guided form. An unknown category key is simply
  // dropped (the ticket still opens); a service id that is not the caller's
  // own is refused outright rather than silently ignored, so a stale picker
  // never files a ticket against "nothing" while the customer thinks it named
  // their server.
  const category = ticketCategory(String(formData.get("category") ?? ""));
  const rawService = formData.get("service");
  let serviceLabel: string | null = null;
  if (typeof rawService === "string" && rawService !== "") {
    serviceLabel = await resolveOwnedServiceLabel(user.id, rawService);
    if (!serviceLabel) return { error: "That service could not be found on your account. Pick it again or choose \\"Not about a specific service\\"." };
  }

  // Attachments, validated BEFORE the ticket exists — a rejected file must not
  // leave a half-opened ticket behind. Same limits and byte sniffing as a reply.
  const rawFiles = formData.getAll("file").filter((f): f is File => f instanceof File && f.size > 0);
  if (rawFiles.length > MAX_ATTACHMENTS_PER_REPLY) {
    return { error: `Attach at most ${MAX_ATTACHMENTS_PER_REPLY} files per message.` };
  }
  const attachments: { mime: string; name: string; size: number; data: Buffer }[] = [];
  for (const file of rawFiles) {
    if (file.size > MAX_TICKET_ATTACHMENT_BYTES) return { error: `"${file.name}" is larger than 10 MB.` };
    const bytes = Buffer.from(await file.arrayBuffer());
    const check = validateTicketAttachmentBytes(bytes, file.type, file.name);
    if (!check.ok) return { error: `"${file.name}": ${check.error}` };
    attachments.push({ mime: check.mime, name: file.name.slice(0, 200) || "attachment", size: check.bytes.length, data: check.bytes });
  }

  const ticket = await createTicketCore({
    userId: user.id,
    subject: parsed.data.subject,
    body: composeTicketBody({ category, serviceLabel, body: parsed.data.body }),
    priority: parsed.data.priority,
  });
  // Files ride behind the opening message as attachment-only messages from the
  // same author — the exact shape replyTicket writes for a multi-file send, so
  // the thread view clusters them into the opening bubble's image grid.
  if (attachments.length) {
    await db.ticketMessage.createMany({
      data: attachments.map((a) => ({
        ticketId: ticket.ticketId,
        body: "",
        authorId: user.id,
        isStaff: false,
        attachmentData: new Uint8Array(a.data),
        attachmentMime: a.mime,
        attachmentName: a.name,
        attachmentSize: a.size,
      })),
    });
  }
  // Discord bridge (Phase 1 mirror): best-effort, never blocks ticket creation
  // or the redirect below — see lib/discord-bridge.ts's top-of-file comment.
  await mirrorNewTicketToDiscord(ticket.ticketId);
  redirect(`/dashboard/support/${ticket.ticketId}`);
}

