new=r'''export function NewTicketForm({
  open: openProp, onOpenChange, services = [], articles = [], defaultCategory = null,
}: {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** The customer's own services for the "Which service?" picker. Optional:
   *  without it the picker is simply not shown. createTicket re-checks
   *  ownership of whatever is submitted. */
  services?: ServiceOption[];
  /** Published help-article titles for live suggestions while typing. */
  articles?: HelpArticleLite[];
  defaultCategory?: TicketCategoryKey | null;
} = {}) {
  // Controlled if a parent passes `open`/`onOpenChange` (the Support page's
  // header CTA opens this same form from outside it), otherwise manages its
  // own state exactly as before — every other/future plain `<NewTicketForm/>`
  // call site is unaffected.
  const [openState, setOpenState] = useState(false);
  const open = openProp ?? openState;
  const setOpen = onOpenChange ?? setOpenState;
  const [state, action, pending] = useActionState(createTicket, {});
  // CONTROLLED, deliberately. React 19 resets uncontrolled inputs on every
  // `<form action={fn}>` submit, so a rejected ticket came back with the subject
  // and the body — up to 10,000 characters — blank. The person retyping it is by
  // definition someone who already has a problem and has just been told "no".
  //
  // This is the same reset that permanently locked customers out of 2FA login
  // (see components/AuthForms.tsx). There the cost was the account; here it is
  // the customer's own words, which they will not write twice.
  const [subject, setSubject] = useState("");
  const [priority, setPriority] = useState("NORMAL");
  const [body, setBody] = useState("");
  const [category, setCategory] = useState<TicketCategoryKey | null>(defaultCategory);
  const [service, setService] = useState("");
  const composerRef = useRef<ReplyComposerHandle>(null);
  const dialogRef = useRef<HTMLDivElement>(null);
  const titleId = useId();

  const cat = ticketCategory(category);
  const showService = services.length > 0 && (cat === null || cat.wantsService);
  // A service picked under "Server" and then a switch to "Billing" must not
  // ride along invisibly on the submit.
  const submittedService = showService ? service : "";

  const suggestions = useMemo(
    () => suggestArticles(`${subject} ${body}`, articles, { category, limit: 3 }),
    [subject, body, articles, category],
  );

  const groups = useMemo(() => {
    const g: { label: string; items: ServiceOption[] }[] = [
      { label: "Servers", items: services.filter((s) => s.kind === "server" && !s.game) },
      { label: "Game servers", items: services.filter((s) => s.kind === "server" && s.game) },
      { label: "Web hosting", items: services.filter((s) => s.kind === "hosting") },
      { label: "Domains", items: services.filter((s) => s.kind === "domain") },
    ];
    return g.filter((x) => x.items.length > 0);
  }, [services]);

  // Esc closes the modal, same as clicking the backdrop or the X — standard
  // dialog behaviour. Focus moves into the dialog on open and back to
  // whatever opened it on close.
  useEffect(() => {
    if (!open) return;
    const opener = document.activeElement as HTMLElement | null;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setOpen(false); };
    window.addEventListener("keydown", onKey);
    const t = setTimeout(() => dialogRef.current?.querySelector<HTMLElement>("[data-autofocus]")?.focus(), 30);
    return () => { window.removeEventListener("keydown", onKey); clearTimeout(t); opener?.focus?.(); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  return (
    <>
      {/* Controlled usage supplies its own trigger button elsewhere (the
          Support page's "New ticket" CTAs) — rendering one here too would be
          redundant. Uncontrolled usage still needs its own. */}
      {openProp === undefined && (
        <div className="flex justify-end">
          <button className="btn-primary" onClick={() => setOpen(true)}>+ New ticket</button>
        </div>
      )}
      {open && (
        <div
          className="fixed inset-0 z-[80] flex items-end justify-center bg-black/60 backdrop-blur-sm motion-safe:animate-fade-up sm:items-center sm:p-4"
          onClick={(e) => { if (e.target === e.currentTarget) setOpen(false); }}
        >
          {/* The scroll lives on an INNER wrapper, not this card itself —
              `.card-glass`'s corner-glow pseudo-elements bleed outside their
              own box on purpose (see globals.css), and putting `overflow-y`
              on the same element that draws them clips that glow against the
              scrollport. Below `sm` this is a bottom sheet (thumb-reachable
              actions, safe-area padding), above it a centred dialog. */}
          <div ref={dialogRef} role="dialog" aria-modal="true" aria-labelledby={titleId}
               className="card card-glass relative flex max-h-[92dvh] w-full max-w-[720px] flex-col rounded-b-none p-0 sm:max-h-[90dvh] sm:rounded-b-[inherit]"
               style={{ "--tone": "#8c3ae9" } as React.CSSProperties}>
            <div className="mx-auto mt-2 h-1 w-10 flex-none rounded-full bg-rim-hi sm:hidden" aria-hidden />
            <div className="flex flex-none items-start justify-between gap-3 px-5 pb-3 pt-4 sm:px-6 sm:pt-6">
              <div className="flex min-w-0 items-start gap-3">
                <span className="nx-sup-plate hidden h-10 w-10 flex-none sm:grid" aria-hidden>
                  <Icon name="chatdots" size={16} tone="inherit" />
                </span>
                <span className="flex min-w-0 flex-col gap-0.5">
                  <h2 id={titleId} className="text-[18px] font-extrabold tracking-[-0.02em] text-white">Open a support ticket</h2>
                  <span className="text-[12.5px] leading-[1.45] text-tx-mute">
                    A person on our team replies {SUPPORT_REPLY_WITHIN} — outages and urgent server issues are picked up first.
                  </span>
                </span>
              </div>
              <button type="button" aria-label="Close" onClick={() => setOpen(false)}
                      className="nx-inline flex-none rounded-lg p-1.5 text-tx-faint hover:bg-white/10 hover:text-white">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
                  <path d="M18 6 6 18M6 6l12 12" />
                </svg>
              </button>
            </div>
            <form action={action} onSubmit={() => composerRef.current?.flushAttachment()}
                  className="flex min-h-0 flex-1 flex-col">
              <div className="flex-1 space-y-5 overflow-y-auto px-5 pb-4 sm:px-6">
                {state?.error && (
                  <div role="alert" className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
                    {state.error}
                  </div>
                )}

                <fieldset>
                  <legend className="label">What is it about?</legend>
                  <input type="hidden" name="category" value={category ?? ""} />
                  <div className="grid grid-cols-2 gap-2 sm:grid-cols-3" role="radiogroup">
                    {TICKET_CATEGORIES.map((c, i) => {
                      const on = c.key === category;
                      return (
                        <button key={c.key} type="button" role="radio" aria-checked={on}
                                data-autofocus={i === 0 ? true : undefined}
                                onClick={() => setCategory(on ? null : c.key)}
                                className={"nx-sup-choice flex min-h-[64px] items-start gap-2.5 p-3 text-left " + (on ? "nx-sup-choice-on" : "")}>
                          <span className="nx-sup-choice-ico grid h-8 w-8 flex-none place-items-center" aria-hidden>
                            <Icon name={c.icon} size={14} tone="inherit" />
                          </span>
                          <span className="flex min-w-0 flex-col gap-0.5">
                            <span className="text-[13px] font-bold leading-tight text-white">{c.label}</span>
                            <span className="text-[11.5px] leading-tight text-tx-faint">{c.hint}</span>
                          </span>
                        </button>
                      );
                    })}
                  </div>
                </fieldset>

                {showService && (
                  <div>
                    <label className="label" htmlFor={`${titleId}-svc`}>Which service?</label>
                    <select id={`${titleId}-svc`} className="input" name="service" value={submittedService}
                            onChange={(e) => setService(e.target.value)}>
                      <option value="">Not about a specific service</option>
                      {groups.map((g) => (
                        <optgroup key={g.label} label={g.label}>
                          {g.items.map((s) => (
                            <option key={s.value} value={s.value}>
                              {s.label}{s.detail ? ` — ${s.detail}` : ""}
                            </option>
                          ))}
                        </optgroup>
                      ))}
                    </select>
                  </div>
                )}

                <div>
                  <label className="label" htmlFor={`${titleId}-subj`}>Subject</label>
                  <input
                    id={`${titleId}-subj`}
                    className="input"
                    name="subject"
                    required
                    minLength={3}
                    maxLength={150}
                    value={subject}
                    onChange={(e) => setSubject(e.target.value)}
                    placeholder="Briefly, what's going on?"
                  />
                </div>

                {suggestions.length > 0 && (
                  <div className="nx-sup-suggest rounded-[12px] p-3" aria-live="polite">
                    <span className="flex items-center gap-1.5 text-[12px] font-bold text-white">
                      <Icon name="sparkles" size={12} tone="inherit" />
                      These might answer it right now
                    </span>
                    <ul className="mt-1.5 flex flex-col">
                      {suggestions.map((a) => (
                        <li key={a.slug}>
                          <a href={`/blog/${a.slug}`} target="_blank" rel="noopener"
                             className="group flex items-center gap-2 rounded-[8px] px-1.5 py-1.5 text-[12.5px] text-tx-body hover:bg-[rgba(72,148,255,0.08)] hover:text-white">
                            <Icon name="file" size={12} tone="inherit" className="flex-none opacity-70" />
                            <span className="min-w-0 flex-1 truncate">{a.title}</span>
                            <span className="flex-none text-[11px] text-tx-faint group-hover:text-cyan">Open ↗</span>
                          </a>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                <fieldset>
                  <legend className="label">Priority</legend>
                  <div className="nx-sup-seg grid grid-cols-4" role="radiogroup">
                    {(["LOW", "NORMAL", "HIGH", "URGENT"] as const).map((v) => (
                      <label key={v} className={"nx-sup-seg-opt " + (priority === v ? "nx-sup-seg-on" : "")} data-prio={v}>
                        <input type="radio" name="priority" value={v} checked={priority === v}
                               onChange={() => setPriority(v)} className="sr-only" />
                        {v === "LOW" ? "Low" : v === "NORMAL" ? "Normal" : v === "HIGH" ? "High" : "Urgent"}
                      </label>
                    ))}
                  </div>
                  <p className="mt-1.5 text-[11.5px] text-tx-faint">
                    {priority === "URGENT" ? "Use Urgent for an outage — a service that is down right now."
                      : priority === "HIGH" ? "Something is broken or degraded but still partly working."
                      : priority === "LOW" ? "A question or a request, no rush."
                      : "Most tickets. We work these in the order they arrive."}
                  </p>
                </fieldset>

                <div>
                  <span className="label">Message</span>
                  <ReplyComposer
                    ref={composerRef}
                    value={body}
                    onChange={setBody}
                    placeholder="What happened, what you expected, and any error messages. Screenshots and logs help — attach or paste them."
                    disabled={pending}
                  />
                </div>
              </div>
              <div className="flex flex-none items-center justify-end gap-2 border-t border-rim-soft px-5 py-3.5 pb-[max(0.875rem,env(safe-area-inset-bottom))] sm:px-6">
                <button type="button" className="btn-secondary px-5" onClick={() => setOpen(false)}>
                  Cancel
                </button>
                <button className="btn-primary px-6" disabled={pending}>
                  {pending ? "Opening…" : "Open ticket"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  );
}

