"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { Icon } from "./Icon";
import { Panel } from "./PageShell";
import { NewTicketForm, ReplyForm, TicketStatusButton } from "@/components/customer/TicketForms";
import { MessageAttachment } from "@/components/support/MessageAttachment";
import { EditableMessageBody } from "@/components/support/EditableMessageBody";
import { getTicketThread, getTypingStatus, type TicketThread } from "@/lib/actions-support";
import { DmMessagesPanel, type DmSummary } from "@/components/nx/DmMessagesPanel";
import ChatWidget, { type ChatViewer } from "@/components/ChatWidget";
import { SupportHeroArt, SupportEmptyArt, SupportNoMatchArt } from "@/components/nx/visual/SupportArt";
import { SUPPORT_REPLY_WINDOW } from "@/lib/support-promise";
import {
  TICKET_FILTERS, matchesTicketFilter, ticketFilterCounts, parseTicketBodyHeader, suggestArticles,
  type TicketFilterKey, type ServiceOption, type HelpArticleLite,
} from "@/lib/support-intake";

/* ── Support, overhauled (2026-10) ──────────────────────────────────────────
 *
 * What changed and why, for whoever opens this next:
 *  - The hero's raster render (public/nx/art/support-hero-banner.webp — an
 *    1800x600 AI image with baked-in copy and an off-brand "NX" mark, ~1x on
 *    retina, unreadable on phones, a black slab in light mode) is replaced by
 *    a vector composition in the brand tokens (components/nx/visual/SupportArt).
 *  - The hero now answers "how do I get help fast?" first: four channels, each
 *    with its REAL live state — the assistant (genuinely always on), tickets
 *    (the shared SUPPORT_REPLY_WINDOW promise + this customer's own measured
 *    first-reply time), service status (lib/monitoring) and the help center.
 *    The old "Fast Response · usually within minutes / Real People" chips are
 *    gone: they contradicted lib/support-promise.ts and the AI assistant.
 *  - The four stat cards became one compact metric strip; the ticket table
 *    became a list of rows that works at 390px (the table hid priority/status
 *    behind a horizontal scroll on phones).
 *  - Help-center categories use vector icons instead of emoji.
 *  - The New ticket form gained category / service / attachments / live
 *    article suggestions (components/customer/TicketForms.tsx).
 *
 * Data honesty notes from the previous version still hold: no CSAT figure
 * (none exists), avg response is measured from this customer's own tickets.
 */

type Ticket = {
  id: string; subject: string; status: string; priority: string;
  updated: string; preview: string; lastFromStaff: boolean;
};

type CompStatus = "operational" | "degraded" | "down";
type HealthComponent = "web" | "db" | "worker" | "proxmox";

type StatusData = {
  overall: CompStatus;
  components: { key: HealthComponent; label: string; status: CompStatus; uptimePct: number | null }[];
  incidents: { id: string; title: string; body: string; severity: "degraded" | "down" | "maintenance"; startedAt: string; resolvedAt: string | null }[];
};

type HelpSectionLite = { name: string; slug: string; emoji: string; blurb: string; count: number };

/* The real TicketStatus values, said in the customer's language. CUSTOMER_REPLY
   means they have answered and staff have not come back yet — "With support" is
   what that means to the person waiting. `tone` is one of nx-tag's hue keys;
   `pulse` only where something is actually waiting on an action. `edge` is the
   row's status filament colour. */
const STATUS: Record<string, { label: string; tone: string; pulse?: boolean; edge: string }> = {
  OPEN:           { label: "Open",          tone: "amber", pulse: true, edge: "amber" },
  ANSWERED:       { label: "Reply waiting", tone: "cyan",  pulse: true, edge: "cyan" },
  CUSTOMER_REPLY: { label: "With support",  tone: "slate", edge: "blue" },
  CLOSED:         { label: "Closed",        tone: "mint",  edge: "rim" },
};

const PRIORITY: Record<string, { label: string; tone: string; pulse?: boolean }> = {
  LOW:    { label: "Low",    tone: "slate" },
  NORMAL: { label: "Normal", tone: "slate" },
  HIGH:   { label: "High",   tone: "amber", pulse: true },
  URGENT: { label: "Urgent", tone: "rose",  pulse: true },
};

/** Same "light, not shape" tag the rest of the portal uses (.nx-tag). */
function StatusTag({ label, tone, pulse, className = "" }: {
  label: string; tone: string; pulse?: boolean; className?: string;
}) {
  return (
    <span className={"nx-tag nx-tag-" + tone + (pulse ? " nx-tag-pulse" : "") + " " + className}>
      <span className="nx-tag-dot" aria-hidden />
      {label}
    </span>
  );
}

const STATUS_DOT: Record<CompStatus, string> = {
  operational: "bg-mint",
  degraded: "bg-amber",
  down: "bg-rose",
};
const OVERALL_TITLE: Record<CompStatus, string> = {
  operational: "All systems operational",
  degraded: "Some systems are degraded",
  down: "We're experiencing an outage",
};

/* Help-center categories (lib/help.ts) → a mark from the vector icon set, in
   place of the emoji the data carries. Unknown categories get `file`. */
const HELP_ICON: Record<string, string> = {
  gaming: "gamepad", vps: "server", tutorials: "file", security: "shieldcheck",
  "control-panels": "sliders", domains: "globe", hosting: "cloud", guides: "lifebuoy",
  comparisons: "barchart",
};

const TABS = [
  { key: "tickets", label: "Tickets" },
  { key: "messages", label: "Messages" },
  { key: "chat", label: "Live chat" },
  { key: "help", label: "Help center" },
  { key: "status", label: "Service status" },
] as const;
type TabKey = (typeof TABS)[number]["key"];

function ago(iso: string): string {
  const m = Math.max(1, Math.round((Date.now() - new Date(iso).getTime()) / 60000));
  if (m < 60) return `${m}m ago`;
  const h = Math.round(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.round(h / 24)}d ago`;
}

function fmtMinutes(min: number): string {
  if (min < 60) return `${min}m`;
  const h = Math.floor(min / 60);
  if (h < 48) return `${h}h ${min % 60 ? `${min % 60}m` : ""}`.trim();
  return `${Math.round(h / 24)}d`;
}

function fmtDate(iso: string): string {
  return new Date(iso).toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" });
}

/** The real cuid, shortened for a scannable reference — not an invented
 *  sequence number, just less of the real id. */
function shortRef(id: string): string {
  return "#" + id.slice(-6).toUpperCase();
}

export function SupportView({
  viewer, viewerId, tickets, open, waitingOnYou, closedRecently, avgResponseMin, initialTicketId,
  dms, initialDmId,
  help, helpTotal, status, services = [], articles = [],
}: {
  viewer: ChatViewer;
  /** The signed-in customer's own id — needed only so the thread view can
   *  tell "my message, still in the 5-minute edit window" apart from a staff
   *  reply; everything else here already scopes to this user server-side. */
  viewerId: string;
  tickets: Ticket[]; open: number; waitingOnYou: number; closedRecently: number;
  avgResponseMin: number | null;
  initialTicketId: string | null;
  /** Staff-initiated direct messages (StaffDm) — a separate inbox from
   *  tickets above, see prisma/schema.prisma's StaffDm doc comment. */
  dms: DmSummary[];
  initialDmId: string | null;
  help: HelpSectionLite[]; helpTotal: number;
  status: StatusData;
  /** The customer's own services, for the New ticket form's service picker. */
  services?: ServiceOption[];
  /** Published help-article titles, for search + suggestions. */
  articles?: HelpArticleLite[];
}) {
  const router = useRouter();
  const [tab, setTab] = useState<TabKey>("tickets");
  const [q, setQ] = useState("");
  const [filter, setFilter] = useState<TicketFilterKey>("all");
  const [newTicketOpen, setNewTicketOpen] = useState(false);
  const [helpQ, setHelpQ] = useState("");

  const [openTicket, setOpenTicket] = useState<TicketThread | null>(null);
  const [ticketErr, setTicketErr] = useState<string | null>(null);
  const [ticketLoading, setTicketLoading] = useState(false);
  const [staffTyping, setStaffTyping] = useState(false);
  const openedInitial = useRef(false);
  const tabsRef = useRef<HTMLDivElement>(null);

  async function openTicketById(id: string) {
    setTicketErr(null);
    setTicketLoading(true);
    const res = await getTicketThread(id);
    setTicketLoading(false);
    if ("error" in res) { setTicketErr("That ticket couldn't be found."); return; }
    setOpenTicket(res);
    router.replace(`/dashboard/support?ticket=${id}`, { scroll: false });
  }

  async function refreshOpenTicket(id: string) {
    const res = await getTicketThread(id);
    if (!("error" in res)) setOpenTicket(res);
  }

  function backToList() {
    setOpenTicket(null);
    setTicketErr(null);
    router.replace("/dashboard/support", { scroll: false });
  }

  function goTab(key: TabKey) {
    setTab(key);
    // From the hero's channel cards: bring the tab content into view, so a
    // tap on a phone visibly does something.
    requestAnimationFrame(() => tabsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }));
  }

  // A deep link (?ticket=, or the redirect shim at /dashboard/support/[id])
  // opens straight into that ticket's thread, once, on first mount.
  useEffect(() => {
    if (openedInitial.current) return;
    openedInitial.current = true;
    if (initialTicketId) { setTab("tickets"); void openTicketById(initialTicketId); }
    else if (initialDmId) { setTab("messages"); }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialTicketId, initialDmId]);

  // No revalidatePath re-render reaches this client-held thread (it isn't
  // server-rendered), so it polls for a staff reply the same way ChatWidget
  // polls its own transcript. ReplyForm/TicketStatusButton's callbacks cover
  // the customer's OWN actions immediately; this covers staff answering
  // while the thread is open.
  useEffect(() => {
    if (!openTicket) return;
    const id = openTicket.id;
    const t = setInterval(() => { void refreshOpenTicket(id); }, 3000);
    return () => clearInterval(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [openTicket?.id]);

  // "Staff is typing" — a much cheaper poll (in-memory map, no DB query).
  useEffect(() => {
    setStaffTyping(false);
    if (!openTicket || openTicket.status === "CLOSED") return;
    const id = openTicket.id;
    let cancelled = false;
    const t = setInterval(async () => {
      const res = await getTypingStatus(id);
      if (!cancelled) setStaffTyping(res.typing);
    }, 1200);
    return () => { cancelled = true; clearInterval(t); };
  }, [openTicket?.id, openTicket?.status]);

  const counts = useMemo(() => ticketFilterCounts(tickets.map((t) => t.status)), [tickets]);
  const shown = tickets.filter((t) => {
    if (!matchesTicketFilter(t.status, filter)) return false;
    const needle = q.trim().toLowerCase();
    if (!needle) return true;
    return t.subject.toLowerCase().includes(needle) || t.preview.toLowerCase().includes(needle)
      || shortRef(t.id).toLowerCase().includes(needle.replace(/^#?/, "#"));
  });

  const helpHits = useMemo(() => suggestArticles(helpQ, articles, { limit: 5 }), [helpQ, articles]);
  const firstName = (viewer.name ?? "").trim().split(/\s+/)[0] || null;
  const incidentsOpen = status.incidents.filter((i) => !i.resolvedAt).length;

  return (
    <div className="nx-sup relative mx-auto flex w-full max-w-[1520px] flex-col gap-4">
      {/* ── Hero: how to get help, fast ───────────────────────────────── */}
      <header className="nx-sup-hero card relative overflow-hidden p-0">
        <span aria-hidden className="nx-sup-hero-wash pointer-events-none absolute inset-0" />
        <div className="relative grid items-center gap-2 md:grid-cols-[minmax(0,1fr)_minmax(0,46%)]">
          <div className="flex min-w-0 flex-col gap-4 px-5 pb-2 pt-6 sm:px-8 sm:pt-8 md:pb-8">
            <span className="nx-sup-eyebrow">
              <span className="h-[6px] w-[6px] rounded-full bg-cyan" aria-hidden />
              Support
            </span>
            <h1 className="text-[30px] font-extrabold leading-[1.06] tracking-[-0.035em] text-white sm:text-[42px]">
              {firstName ? <>How can we <span className="nx-sup-grad">help</span>, {firstName}?</>
                         : <>How can we <span className="nx-sup-grad">help</span>?</>}
            </h1>
            <p className="max-w-[56ch] text-[14px] leading-[1.6] text-tx-mute">
              Ask the assistant for an instant answer, search the guides, or open a ticket and a
              person on our team will reply within {SUPPORT_REPLY_WINDOW}.
            </p>

            {/* Search the help center from right here. Results are the same
                keyword ranking the New ticket form uses; Enter goes to the full
                /help search. */}
            <form action="/help" method="get" role="search" className="relative max-w-[560px]">
              <label htmlFor="nx-sup-search" className="sr-only">Search help articles</label>
              <span className="nx-sup-search">
                <Icon name="search" size={15} tone="inherit" />
                <input id="nx-sup-search" name="q" value={helpQ} onChange={(e) => setHelpQ(e.target.value)}
                       autoComplete="off" placeholder="Search guides — e.g. “SSH timed out”"
                       className="min-w-0 flex-1 bg-transparent text-[14px] text-white outline-none placeholder:text-tx-faint" />
                <button type="submit" className="nx-inline flex-none rounded-[9px] px-2.5 py-1 text-[12px] font-bold text-tx-dim hover:text-white">
                  Search
                </button>
              </span>
              {helpQ.trim().length > 1 && (
                <div className="nx-sup-results absolute inset-x-0 top-[calc(100%+6px)] z-20 p-1.5" role="listbox" aria-label="Matching help articles">
                  {helpHits.length === 0 ? (
                    <span className="block px-3 py-2.5 text-[12.5px] text-tx-faint">
                      No guide matches yet — press Enter to search everything, or open a ticket.
                    </span>
                  ) : helpHits.map((a) => (
                    <a key={a.slug} href={`/blog/${a.slug}`} role="option" aria-selected={false}
                       className="flex items-center gap-2.5 rounded-[9px] px-2.5 py-2 text-[13px] text-tx-body hover:bg-[rgba(72,148,255,0.08)] hover:text-white">
                      <Icon name="file" size={13} tone="inherit" className="flex-none opacity-70" />
                      <span className="min-w-0 flex-1 truncate">{a.title}</span>
                      <span className="flex-none text-[11px] text-tx-faint">{a.category}</span>
                    </a>
                  ))}
                </div>
              )}
            </form>

            <div className="flex flex-wrap items-center gap-2.5">
              <button type="button"
                      onClick={() => { setTab("tickets"); backToList(); setNewTicketOpen(true); }}
                      className="btn-primary flex h-[42px] items-center gap-2 px-5 text-[13.5px]">
                <Icon name="plus" size={13} tone="inherit" />
                New ticket
              </button>
              <button type="button" onClick={() => goTab("chat")}
                      className="btn-secondary flex h-[42px] items-center gap-2 px-4 text-[13.5px]">
                <span className="nx-sup-live" aria-hidden />
                Chat with us
              </button>
            </div>
          </div>
          <div className="pointer-events-none relative hidden h-full min-h-[300px] items-center justify-center md:flex" aria-hidden>
            <SupportHeroArt className="h-auto w-full max-w-[560px]" />
          </div>
        </div>

        {/* Metric strip — this customer's own numbers. */}
        <dl className="nx-sup-metrics relative grid grid-cols-2 sm:grid-cols-4">
          {[
            { k: "Open tickets", v: String(open), tone: "blue" },
            { k: "Waiting for you", v: String(waitingOnYou), tone: waitingOnYou > 0 ? "cyan" : "dim" },
            { k: "Resolved · 30 days", v: String(closedRecently), tone: "mint" },
            { k: "Your avg first reply", v: avgResponseMin === null ? "—" : fmtMinutes(avgResponseMin), tone: "violet",
              note: avgResponseMin === null ? "Not enough data yet" : undefined },
          ].map((m) => (
            <div key={m.k} className="nx-sup-metric" data-tone={m.tone}>
              <dt className="text-[11.5px] font-semibold text-tx-faint">{m.k}</dt>
              <dd className="num text-[22px] leading-none text-white">
                {m.v}
                {m.note && <span className="ml-2 align-middle text-[11px] font-normal text-tx-faint">{m.note}</span>}
              </dd>
            </div>
          ))}
        </dl>
      </header>

      {/* ── Ways to get help — each with its real, current state ─────────── */}
      <section aria-label="Ways to get help" className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
        <ChannelCard icon="chatdots" tone="violet" title="Live chat"
                     state={<><span className="nx-sup-live" aria-hidden /> Assistant online now</>}
                     body="Instant answers about your services and invoices — it brings in our team when it can't solve it."
                     cta="Start a chat" onClick={() => goTab("chat")} />
        <ChannelCard icon="lifebuoy" tone="blue" title="Open a ticket"
                     state={<>Replies within {SUPPORT_REPLY_WINDOW}</>}
                     body={avgResponseMin !== null
                       ? `Your tickets have had a first reply in ${fmtMinutes(avgResponseMin)} on average.`
                       : "Best for anything that needs a person to look at your server or account."}
                     cta="New ticket" onClick={() => { setTab("tickets"); backToList(); setNewTicketOpen(true); }} />
        <ChannelCard icon="activity" tone={status.overall === "operational" ? "mint" : status.overall === "degraded" ? "amber" : "rose"}
                     title="Service status"
                     state={<><span className={"h-[7px] w-[7px] rounded-full " + STATUS_DOT[status.overall]} aria-hidden /> {OVERALL_TITLE[status.overall]}</>}
                     body={incidentsOpen > 0
                       ? `${incidentsOpen} incident${incidentsOpen === 1 ? "" : "s"} in progress — check here before opening a ticket.`
                       : "Check here first if something just stopped working."}
                     cta="View status" onClick={() => goTab("status")} />
        <ChannelCard icon="file" tone="cyan" title="Help center"
                     state={<>{helpTotal} guides &amp; tutorials</>}
                     body="Step-by-step fixes for servers, game servers, domains, email and billing."
                     cta="Browse guides" onClick={() => goTab("help")} />
      </section>

      {/* Same underlined-text tab language as Billing (.nx-tab/.nx-tab-on). One
          row that scrolls sideways on a phone instead of wrapping into two. */}
      <div ref={tabsRef} className="nx-sup-tabs -mx-1 flex scroll-mt-20 items-end gap-6 overflow-x-auto border-b border-rim-soft px-1 pt-1" role="tablist">
        {TABS.map((t) => {
          const badge = t.key === "tickets" ? (waitingOnYou || null)
                      : t.key === "messages" ? (dms.filter((d) => d.unreadForCustomer).length || null)
                      : null;
          return (
            <button key={t.key} type="button" role="tab" aria-selected={tab === t.key} onClick={() => setTab(t.key)}
                    className={"nx-tab flex flex-none items-center gap-1.5 whitespace-nowrap " + (tab === t.key ? "nx-tab-on" : "")}>
              {t.label}
              {t.key === "chat" && <span className="nx-sup-live" aria-label="online" />}
              {badge !== null && <span className="nx-sup-badge" aria-label={`${badge} need attention`}>{badge}</span>}
            </button>
          );
        })}
      </div>

      {tab === "tickets" && (
        <div className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_320px]">
          <section className="card flex min-w-0 flex-col p-0">
            {ticketLoading ? (
              <div className="flex items-center justify-center py-16" role="status" aria-label="Loading ticket">
                <span className="h-6 w-6 animate-spin rounded-full border-2 border-rim-hi border-t-cyan" />
              </div>
            ) : ticketErr ? (
              <div className="flex flex-col items-center gap-3 px-6 py-12 text-center">
                <SupportNoMatchArt className="h-[88px] w-auto" />
                <span className="text-[14px] font-bold text-white">{ticketErr}</span>
                <button type="button" onClick={backToList} className="btn-secondary h-[34px] px-4 text-[12.5px]">← Back to tickets</button>
              </div>
            ) : openTicket ? (
              <TicketThreadPanel ticket={openTicket} viewerId={viewerId} onBack={backToList}
                                  onSent={() => refreshOpenTicket(openTicket.id)} staffTyping={staffTyping} />
            ) : (
              <>
                <div className="flex flex-col gap-3 border-b border-rim-soft px-4 pb-3 pt-4 sm:px-5">
                  <div className="flex items-start justify-between gap-3">
                    <span className="flex min-w-0 flex-col gap-0.5">
                      <h2 className="text-[16px] font-extrabold tracking-[-0.02em] text-white">Your tickets</h2>
                      <span className="text-[12px] text-tx-faint">
                        {tickets.length === 0 ? "Nothing open — good." : `${shown.length} of ${tickets.length} shown`}
                      </span>
                    </span>
                    {tickets.length > 0 && (
                      <button type="button" onClick={() => setNewTicketOpen(true)}
                              className="btn-secondary flex h-[34px] flex-none items-center gap-1.5 px-3 text-[12.5px]">
                        <Icon name="plus" size={11} tone="inherit" /> New
                      </button>
                    )}
                  </div>
                  {tickets.length > 0 && (
                    <div className="flex flex-col gap-2.5 md:flex-row md:items-center md:justify-between">
                      <div className="nx-sup-chips -mx-1 flex gap-1.5 overflow-x-auto px-1" role="group" aria-label="Filter tickets">
                        {TICKET_FILTERS.map((f) => (
                          <button key={f.key} type="button" aria-pressed={filter === f.key} onClick={() => setFilter(f.key)}
                                  className={"nx-sup-chip flex-none " + (filter === f.key ? "nx-sup-chip-on" : "")}>
                            {f.label}
                            <span className="nx-sup-chip-n">{counts[f.key]}</span>
                          </button>
                        ))}
                      </div>
                      <label className="field h-[36px] w-full md:w-[240px]">
                        <Icon name="search" size={14} />
                        <span className="sr-only">Search tickets</span>
                        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search subject, message or #ref"
                               className="min-w-0 flex-1 bg-transparent text-[12.5px] text-white outline-none placeholder:text-tx-faint" />
                      </label>
                    </div>
                  )}
                </div>

                {tickets.length === 0 ? (
                  <div className="flex flex-col items-center gap-3 px-6 py-12 text-center">
                    <SupportEmptyArt className="h-[120px] w-auto" />
                    <span className="text-[16px] font-extrabold tracking-[-0.02em] text-white">No tickets yet</span>
                    <span className="max-w-[44ch] text-[13px] leading-[1.55] text-tx-mute">
                      When something needs a person, open a ticket — it keeps the whole conversation, your
                      screenshots and our replies in one place.
                    </span>
                    <div className="mt-1 flex flex-wrap justify-center gap-2">
                      <button type="button" onClick={() => setNewTicketOpen(true)} className="btn-primary h-[38px] px-5 text-[13px]">
                        Open a ticket
                      </button>
                      <button type="button" onClick={() => goTab("chat")} className="btn-secondary h-[38px] px-4 text-[13px]">
                        Ask the assistant
                      </button>
                    </div>
                  </div>
                ) : shown.length === 0 ? (
                  <div className="flex flex-col items-center gap-2 px-6 py-12 text-center">
                    <SupportNoMatchArt className="h-[88px] w-auto" />
                    <span className="text-[14px] font-bold text-white">Nothing matches</span>
                    <span className="text-[12.5px] text-tx-faint">Try another search or filter.</span>
                    <button type="button" onClick={() => { setQ(""); setFilter("all"); }} className="btn-ghost mt-1 h-[32px] px-3 text-[12.5px]">
                      Clear filters
                    </button>
                  </div>
                ) : (
                  <ul className="flex flex-col">
                    {shown.map((t) => {
                      const s = STATUS[t.status] ?? { label: t.status, tone: "slate", edge: "rim" };
                      const p = PRIORITY[t.priority] ?? { label: t.priority, tone: "slate" };
                      const loud = t.priority === "HIGH" || t.priority === "URGENT";
                      const preview = parseTicketBodyHeader(t.preview).rest || t.preview;
                      return (
                        <li key={t.id} className="border-b border-rim-soft/70 last:border-0">
                          <button type="button" onClick={() => openTicketById(t.id)} data-edge={s.edge}
                                  className="nx-sup-row group grid w-full grid-cols-[minmax(0,1fr)_auto] items-start gap-x-4 gap-y-2 px-4 py-3.5 text-left sm:px-5">
                            <span className="flex min-w-0 flex-col gap-1">
                              <span className="flex min-w-0 items-baseline gap-2">
                                <span className="truncate text-[14px] font-bold text-white">{t.subject}</span>
                                <span className="mono hidden flex-none text-[11px] text-tx-faint sm:inline">{shortRef(t.id)}</span>
                              </span>
                              {preview && (
                                <span className="truncate text-[12.5px] text-tx-faint">
                                  <span className={t.lastFromStaff ? "font-semibold text-tx-mute" : ""}>
                                    {t.lastFromStaff ? "Support" : "You"}:
                                  </span>{" "}{preview}
                                </span>
                              )}
                            </span>
                            <span suppressHydrationWarning className="flex items-center gap-1.5 whitespace-nowrap pt-0.5 text-[11.5px] text-tx-faint">
                              {ago(t.updated)}
                              <ChevronRight className="transition-transform group-hover:translate-x-0.5" />
                            </span>
                            <span className="col-span-2 flex flex-wrap items-center gap-x-4 gap-y-1">
                              <StatusTag {...s} className="text-[12px]" />
                              <StatusTag {...p} label={loud ? `${p.label} priority` : p.label} className={"text-[12px] " + (loud ? "" : "opacity-80")} />
                              <span className="mono text-[11px] text-tx-faint sm:hidden">{shortRef(t.id)}</span>
                            </span>
                          </button>
                        </li>
                      );
                    })}
                  </ul>
                )}
              </>
            )}
            <NewTicketForm open={newTicketOpen} onOpenChange={setNewTicketOpen} services={services} articles={articles} />
          </section>

          <aside className="flex min-w-0 flex-col gap-3">
            {openTicket ? (
              <TicketDetails ticket={openTicket} onChat={() => goTab("chat")} />
            ) : (
              <>
                <Panel title="Before you open one" sub="The fastest fixes are often already written down">
                  <ul className="-mx-1 flex flex-col">
                    {help.slice(0, 5).map((h) => (
                      <li key={h.slug}>
                        <Link href={`/help?c=${h.slug}`}
                              className="flex items-center gap-3 rounded-[10px] px-1.5 py-2 transition-colors hover:bg-[rgba(72,148,255,0.06)]">
                          <span className="nx-sup-plate grid h-8 w-8 flex-none" aria-hidden>
                            <Icon name={HELP_ICON[h.slug] ?? "file"} size={13} tone="inherit" />
                          </span>
                          <span className="flex min-w-0 flex-1 flex-col">
                            <span className="text-[13px] font-semibold text-white">{h.name}</span>
                            <span className="text-[11.5px] text-tx-faint">{h.count} article{h.count === 1 ? "" : "s"}</span>
                          </span>
                          <ChevronRight className="flex-none" />
                        </Link>
                      </li>
                    ))}
                    <li>
                      <Link href="/dashboard/feedback"
                            className="flex items-center gap-3 rounded-[10px] px-1.5 py-2 transition-colors hover:bg-[rgba(72,148,255,0.06)]">
                        <span className="nx-sup-plate grid h-8 w-8 flex-none" aria-hidden>
                          <Icon name="megaphone" size={13} tone="inherit" />
                        </span>
                        <span className="flex min-w-0 flex-1 flex-col">
                          <span className="text-[13px] font-semibold text-white">Feedback &amp; bug reports</span>
                          <span className="text-[11.5px] text-tx-faint">Tell us what&apos;s broken or missing</span>
                        </span>
                        <ChevronRight className="flex-none" />
                      </Link>
                    </li>
                  </ul>
                </Panel>
                <UrgentNote />
              </>
            )}
          </aside>
        </div>
      )}

      {tab === "messages" && <DmMessagesPanel dms={dms} initialDmId={initialDmId} />}

      {tab === "chat" && (
        <div className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_320px]">
          <Panel title="Live chat" sub="Nxeon Assistant · online now" bodyClass="p-0" className="overflow-hidden">
            {/* The SAME widget that floats on every other page — mounted a
                second time, `embedded`, instead of a second chat UI. It
                genuinely is an AI agent, not a named human rep. */}
            <div className="h-[min(620px,72dvh)]">
              <ChatWidget embedded viewer={viewer} />
            </div>
          </Panel>
          <div className="flex min-w-0 flex-col gap-3">
            <Panel title="What this is">
              <span className="text-[12.5px] leading-[1.55] text-tx-mute">
                Nxeon Assistant is our AI support agent — it answers questions instantly,
                looks up your real services and invoices when asked, and can bring in a
                ticket for anything it can&apos;t resolve on the spot.
              </span>
            </Panel>
            <Panel title="Prefer a ticket?">
              <span className="text-[12.5px] leading-[1.55] text-tx-mute">
                A ticket keeps the whole thread in one place for anyone on our side who
                picks it up later.
              </span>
              <button type="button" onClick={() => { setTab("tickets"); setNewTicketOpen(true); }}
                      className="btn-secondary mt-3 h-[36px] w-full text-[12.5px]">
                Open a ticket instead
              </button>
            </Panel>
          </div>
        </div>
      )}

      {tab === "help" && (
        <Panel title="Help center" sub={`${helpTotal} articles`}
               action={<Link href="/help" className="text-[12px] font-semibold text-cyan hover:text-white">Open help center →</Link>}>
          {help.length === 0 ? (
            <div className="flex flex-col items-center gap-2 py-10 text-center">
              <SupportNoMatchArt className="h-[80px] w-auto" />
              <span className="text-[12.5px] text-tx-faint">No articles published yet.</span>
            </div>
          ) : (
            <div className="grid gap-2.5 sm:grid-cols-2 xl:grid-cols-3">
              {help.map((s) => (
                <Link key={s.slug} href={`/help?c=${s.slug}`}
                      className="card card-i flex items-start gap-3 p-3.5">
                  <span className="nx-sup-plate grid h-10 w-10 flex-none" aria-hidden>
                    <Icon name={HELP_ICON[s.slug] ?? "file"} size={15} tone="inherit" />
                  </span>
                  <span className="flex min-w-0 flex-1 flex-col gap-1">
                    <span className="flex items-center gap-2">
                      <span className="text-[13.5px] font-bold text-white">{s.name}</span>
                      <span className="ml-auto flex-none text-[11.5px] font-bold text-tx-faint">{s.count}</span>
                    </span>
                    <span className="text-[12px] leading-[1.45] text-tx-faint">{s.blurb}</span>
                  </span>
                </Link>
              ))}
            </div>
          )}
        </Panel>
      )}

      {tab === "status" && (
        <div className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_320px]">
          <Panel title="Service status"
                 action={<Link href="/status" className="text-[12px] font-semibold text-cyan hover:text-white">Open status page →</Link>}>
            <div className="nx-sup-overall flex items-center gap-3 rounded-[12px] px-3.5 py-3" data-state={status.overall}>
              <span className="relative grid h-3 w-3 place-items-center" aria-hidden>
                <span className={"absolute h-3 w-3 rounded-full opacity-40 motion-safe:animate-ping " + STATUS_DOT[status.overall]} />
                <span className={"h-[9px] w-[9px] rounded-full " + STATUS_DOT[status.overall]} />
              </span>
              <span className="text-[14px] font-bold text-white">{OVERALL_TITLE[status.overall]}</span>
            </div>
            <ul className="mt-2 flex flex-col">
              {status.components.map((c) => (
                <li key={c.key} className="flex flex-wrap items-center gap-x-3 gap-y-1 border-b border-rim-soft py-3 last:border-0">
                  <span className={"h-[8px] w-[8px] flex-none rounded-full " + STATUS_DOT[c.status]} aria-hidden />
                  <span className="flex-1 text-[13px] font-semibold text-white">{c.label}</span>
                  <span className="text-[12px] text-tx-faint">
                    {c.uptimePct === null ? "Collecting data" : `${c.uptimePct.toFixed(2)}% uptime (90d)`}
                  </span>
                </li>
              ))}
            </ul>
          </Panel>
          <Panel title="Recent incidents">
            {status.incidents.length === 0 ? (
              <span className="py-6 text-center text-[12.5px] text-tx-faint">
                No incidents in the last 90 days.
              </span>
            ) : (
              <ul className="flex flex-col gap-3">
                {status.incidents.map((inc) => (
                  <li key={inc.id} className="flex flex-col gap-0.5">
                    <span className="flex items-center gap-2">
                      <span className={"h-[7px] w-[7px] flex-none rounded-full " +
                        (inc.severity === "down" ? "bg-rose" : inc.severity === "degraded" ? "bg-amber" : "bg-cyan")} aria-hidden />
                      <span className="trunc text-[12.5px] font-semibold text-white">{inc.title}</span>
                    </span>
                    <span suppressHydrationWarning className="pl-[15px] text-[11.5px] text-tx-faint">
                      {inc.resolvedAt ? "Resolved" : "Ongoing"} · {ago(inc.startedAt)}
                    </span>
                  </li>
                ))}
              </ul>
            )}
          </Panel>
        </div>
      )}
    </div>
  );
}

/** One "way to get help" card in the hero row. The whole card is the button. */
function ChannelCard({ icon, tone, title, state, body, cta, onClick }: {
  icon: string; tone: "violet" | "blue" | "cyan" | "mint" | "amber" | "rose";
  title: string; state: React.ReactNode; body: string; cta: string; onClick: () => void;
}) {
  return (
    <button type="button" onClick={onClick} className="nx-sup-channel card card-i group flex flex-col gap-3 p-4 text-left" data-tone={tone}>
      <span className="flex items-center gap-3">
        <span className="nx-sup-channel-ico grid h-10 w-10 flex-none place-items-center" aria-hidden>
          <Icon name={icon} size={15} tone="inherit" />
        </span>
        <span className="flex min-w-0 flex-col gap-0.5">
          <span className="text-[14.5px] font-extrabold tracking-[-0.01em] text-white">{title}</span>
          <span className="flex items-center gap-1.5 text-[12px] font-semibold text-tx-mute">{state}</span>
        </span>
      </span>
      <span className="text-[12.5px] leading-[1.5] text-tx-faint">{body}</span>
      <span className="mt-auto flex items-center gap-1 text-[12.5px] font-bold text-cyan group-hover:text-white">
        {cta} <ChevronRight className="opacity-100 transition-transform group-hover:translate-x-0.5" />
      </span>
    </button>
  );
}

function UrgentNote() {
  return (
    <section className="nx-sup-urgent card flex items-start gap-3 p-4">
      <span className="nx-sup-plate nx-sup-plate-warm grid h-9 w-9 flex-none" aria-hidden>
        <Icon name="bolt" size={14} tone="inherit" />
      </span>
      <span className="flex flex-col gap-1">
        <span className="text-[13px] font-bold text-white">Something down right now?</span>
        <span className="text-[12px] leading-[1.5] text-tx-faint">
          Check service status first, then open a ticket marked <b className="font-semibold text-tx-mute">Urgent</b> and
          pick the affected service — outage tickets are picked up first.
        </span>
      </span>
    </section>
  );
}

/** A plain right-facing chevron — the icon set has no chevron mark. */
function ChevronRight({ className = "" }: { className?: string }) {
  return (
    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"
         strokeLinecap="round" strokeLinejoin="round" className={"opacity-50 " + className} aria-hidden>
      <path d="M9 18l6-6-6-6" />
    </svg>
  );
}

type TicketThreadMessage = TicketThread["messages"][number];

/** A run of consecutive messages from the same author, close enough together
 *  in time to read as one turn of the conversation. This is what turns a
 *  multi-image send (one text message + N attachment-only follow-ups, see
 *  `replyTicket`/`createTicket` in lib/actions-support.ts) back into a single
 *  bubble with an image grid, instead of a wall of near-identical bubbles. */
type MessageCluster = { authorId: string; isStaff: boolean; authorName: string; lastAt: string; messages: TicketThreadMessage[] };

const CLUSTER_GAP_MS = 60_000;

function clusterMessages(messages: TicketThreadMessage[]): MessageCluster[] {
  const clusters: MessageCluster[] = [];
  for (const m of messages) {
    const last = clusters[clusters.length - 1];
    const gap = last ? new Date(m.createdAt).getTime() - new Date(last.lastAt).getTime() : Infinity;
    if (last && last.authorId === m.authorId && last.isStaff === m.isStaff && gap <= CLUSTER_GAP_MS) {
      last.messages.push(m);
      last.lastAt = m.createdAt;
    } else {
      clusters.push({ authorId: m.authorId, isStaff: m.isStaff, authorName: m.authorName, lastAt: m.createdAt, messages: [m] });
    }
  }
  return clusters;
}

function initialsOf(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  return (parts[0][0] + (parts[1]?.[0] ?? "")).toUpperCase();
}

function Avatar({ isStaff, name }: { isStaff: boolean; name: string }) {
  return (
    <span className={"nx-sup-avatar grid h-8 w-8 flex-none place-items-center rounded-full text-[11px] font-bold " + (isStaff ? "nx-sup-avatar-staff" : "")} aria-hidden>
      {initialsOf(name)}
    </span>
  );
}

/** The right-rail summary while a thread is open. */
function TicketDetails({ ticket, onChat }: { ticket: TicketThread; onChat: () => void }) {
  const s = STATUS[ticket.status] ?? { label: ticket.status, tone: "slate", edge: "rim" };
  const p = PRIORITY[ticket.priority] ?? { label: ticket.priority, tone: "slate" };
  const head = parseTicketBodyHeader(ticket.messages[0]?.body ?? "");
  const last = ticket.messages[ticket.messages.length - 1];
  const rows: [string, React.ReactNode][] = [
    ["Reference", <span key="r" className="mono">{shortRef(ticket.id)}</span>],
    ["Status", <StatusTag key="s" {...s} className="text-[12px]" />],
    ["Priority", <StatusTag key="p" {...p} className="text-[12px]" />],
    ...(head.category ? [["Category", head.category.label] as [string, React.ReactNode]] : []),
    ...(head.service ? [["Service", head.service] as [string, React.ReactNode]] : []),
    ["Opened", <span key="o" suppressHydrationWarning>{fmtDate(ticket.createdAt)}</span>],
    ["Last activity", <span key="l" suppressHydrationWarning>{last ? ago(last.createdAt) : "—"}</span>],
    ["Messages", String(ticket.messages.filter((m) => m.body).length)],
  ];
  return (
    <>
      <Panel title="Ticket details">
        <dl className="flex flex-col">
          {rows.map(([k, v]) => (
            <div key={k} className="flex items-start justify-between gap-3 border-b border-rim-soft py-2.5 text-[12.5px] last:border-0">
              <dt className="flex-none text-tx-faint">{k}</dt>
              <dd className="min-w-0 break-words text-right font-semibold text-white">{v}</dd>
            </div>
          ))}
        </dl>
      </Panel>
      <section className="card flex items-start gap-3 p-4">
        <span className="nx-sup-plate grid h-9 w-9 flex-none" aria-hidden>
          <Icon name="chatdots" size={14} tone="inherit" />
        </span>
        <span className="flex flex-col gap-1.5">
          <span className="text-[13px] font-bold text-white">Need an answer sooner?</span>
          <span className="text-[12px] leading-[1.5] text-tx-faint">
            The assistant can look at your services right now while this ticket waits for a person.
          </span>
          <button type="button" onClick={onChat} className="nx-inline self-start text-[12.5px] font-bold text-cyan hover:text-white">
            Ask the assistant →
          </button>
        </span>
      </section>
    </>
  );
}

/** The ticket thread — same real components/logic the old full-page route
 *  rendered (ReplyForm, TicketStatusButton, MessageAttachment,
 *  EditableMessageBody), inline instead of a page navigation. */
function TicketThreadPanel({
  ticket, viewerId, onBack, onSent, staffTyping,
}: { ticket: TicketThread; viewerId: string; onBack: () => void; onSent: () => void; staffTyping: boolean }) {
  const s = STATUS[ticket.status] ?? { label: ticket.status, tone: "slate", edge: "rim" };
  const p = PRIORITY[ticket.priority] ?? { label: ticket.priority, tone: "slate" };
  const clusters = clusterMessages(ticket.messages);
  const scrollRef = useRef<HTMLDivElement>(null);
  const count = ticket.messages.length;

  // Land on the newest message (only the desktop inner scroller scrolls; on a
  // phone the thread is part of the page and reads top-down).
  useEffect(() => {
    const el = scrollRef.current;
    if (el && el.scrollHeight > el.clientHeight) el.scrollTop = el.scrollHeight;
  }, [count, staffTyping]);

  return (
    <div className="flex min-w-0 flex-col" data-thread>
      <div className="flex flex-wrap items-start justify-between gap-3 border-b border-rim-soft px-4 pb-3.5 pt-4 sm:px-5">
        <div className="flex min-w-0 items-start gap-3">
          <button type="button" onClick={onBack} aria-label="Back to tickets"
                  className="grid h-[34px] w-[34px] flex-none place-items-center rounded-[10px] border border-rim-hi bg-well text-tx-dim hover:bg-[rgba(72,148,255,0.08)] hover:text-white">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"
                 strokeLinecap="round" strokeLinejoin="round" aria-hidden>
              <path d="M15 18l-6-6 6-6" />
            </svg>
          </button>
          <span className="flex min-w-0 flex-col gap-1.5">
            <h2 className="text-[16.5px] font-extrabold leading-snug tracking-[-0.02em] text-white">{ticket.subject}</h2>
            <span className="flex flex-wrap items-center gap-x-4 gap-y-1">
              <span className="mono text-[11.5px] text-tx-faint">{shortRef(ticket.id)}</span>
              <StatusTag {...s} className="text-[12px]" />
              <StatusTag {...p} className="text-[12px]" />
            </span>
          </span>
        </div>
        <TicketStatusButton ticketId={ticket.id} status={ticket.status} onChanged={onSent} />
      </div>

      <div ref={scrollRef} className="flex flex-col gap-5 px-4 py-5 sm:px-5 lg:max-h-[min(62vh,640px)] lg:overflow-y-auto"
           aria-live="polite" aria-label="Conversation">
        {clusters.map((c, ci) => {
          const single = c.messages.length === 1;
          const m0 = c.messages[0];
          // The opening message's Category/Service header (written by
          // createTicket) is shown as chips, not as raw text.
          const head = ci === 0 && !c.isStaff ? parseTicketBodyHeader(m0.body) : null;
          const text = head && (head.category || head.service) ? head.rest : m0.body;
          const editable = !head?.category && !head?.service;
          const bubble = c.isStaff ? "nx-sup-bubble nx-sup-bubble-staff" : "nx-sup-bubble nx-sup-bubble-me";
          return (
            <div key={m0.id} className={`nx-msg-in flex justify-start gap-2.5 ${c.isStaff ? "" : "flex-row-reverse"}`}>
              <Avatar isStaff={c.isStaff} name={c.authorName} />
              <div className={`flex min-w-0 max-w-[88%] flex-col gap-1.5 sm:max-w-[74%] ${c.isStaff ? "items-start" : "items-end"}`}>
                <span className={`flex flex-wrap items-baseline gap-x-1.5 px-1 text-[12px] font-semibold ${c.isStaff ? "text-brand-300" : "text-tx-mute"}`}>
                  {c.isStaff ? <>{c.authorName} <span className="nx-sup-staffpill">Nxeon team</span></> : c.authorName}
                  <span suppressHydrationWarning className="font-normal text-tx-faint">· {ago(c.lastAt)}</span>
                </span>

                {head && (head.category || head.service) && (
                  <span className="flex flex-wrap justify-end gap-1.5">
                    {head.category && <span className="nx-sup-meta"><Icon name={head.category.icon} size={10} tone="inherit" />{head.category.label}</span>}
                    {head.service && <span className="nx-sup-meta"><Icon name="server" size={10} tone="inherit" />{head.service}</span>}
                  </span>
                )}

                <div className={(single ? "" : "flex flex-col gap-2 ") + bubble}>
                  {single && editable ? (
                    <EditableMessageBody
                      messageId={m0.id}
                      initialBody={m0.body}
                      createdAtIso={m0.createdAt}
                      editedAtIso={m0.editedAt}
                      canEditPermission={m0.authorId === viewerId && ticket.status !== "CLOSED"}
                      bodyClassName="whitespace-pre-wrap break-words text-[13.5px] leading-[1.6] text-tx-body"
                    />
                  ) : (
                    /* Multi-part sends and the header-carrying opening message
                       render plainly — editing those is out of scope. */
                    text && <p className="whitespace-pre-wrap break-words text-[13.5px] leading-[1.6] text-tx-body">{text}</p>
                  )}
                  {single ? (
                    m0.attachmentMime && m0.attachmentName && (
                      <MessageAttachment messageId={m0.id} mime={m0.attachmentMime} name={m0.attachmentName} size={m0.attachmentSize} />
                    )
                  ) : (
                    <div className="grid grid-cols-2 gap-1.5 sm:grid-cols-3">
                      {c.messages.map((m) =>
                        m.attachmentMime && m.attachmentName ? (
                          <MessageAttachment key={m.id} messageId={m.id} mime={m.attachmentMime} name={m.attachmentName} size={m.attachmentSize} />
                        ) : null
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>
          );
        })}

        {staffTyping && (
          <div className="nx-msg-in flex items-center gap-2.5">
            <Avatar isStaff name="Nxeon team" />
            <div className="nx-sup-bubble nx-sup-bubble-staff flex items-center gap-2 !py-2.5">
              <span className="nx-typing" aria-hidden><span /><span /><span /></span>
              <span className="text-[12px] text-tx-faint">Our team is typing…</span>
            </div>
          </div>
        )}
      </div>

      <div className="border-t border-rim-soft px-4 py-4 sm:px-5">
        {ticket.status === "CLOSED" ? (
          <div className="flex flex-col items-center gap-1 rounded-[12px] border border-dashed border-rim-hi bg-well px-4 py-4 text-center">
            <span className="text-[13px] font-bold text-white">This ticket is closed</span>
            <span className="text-[12px] text-tx-faint">Reopen it above to continue the conversation, or open a new ticket.</span>
          </div>
        ) : (
          <ReplyForm ticketId={ticket.id} onSent={onSent} />
        )}
      </div>
    </div>
  );
}

