/* ── /dashboard/support — page-scoped styles (nx-sup-*) ─────────────────────
 *
 * Kept out of app/globals.css on purpose: three page overhauls (Support,
 * Domains, SSL) are landing in parallel and a shared append-at-the-end block
 * in globals.css is a guaranteed merge conflict. Every rule here is prefixed
 * `nx-sup-` and only ever renders on the Support page (SupportView + the New
 * ticket dialog in components/customer/TicketForms.tsx).
 *
 * Colours come exclusively from the theme tokens, so light mode follows
 * `html[data-theme="light"]` without a second palette; the few rules below
 * that are light-specific only soften washes that would otherwise read as
 * grey smudges on a white surface.
 */

/* tone → --t, shared by every component that takes data-tone */
.nx-sup [data-tone="blue"], .nx-sup-tone-blue { --t: var(--color-blue); }
.nx-sup [data-tone="violet"] { --t: var(--color-violet); }
.nx-sup [data-tone="cyan"] { --t: var(--color-cyan); }
.nx-sup [data-tone="mint"] { --t: var(--color-mint); }
.nx-sup [data-tone="amber"] { --t: var(--color-amber); }
.nx-sup [data-tone="rose"] { --t: var(--color-rose); }
.nx-sup [data-tone="dim"] { --t: var(--color-tx-faint); }

/* ── hero ── */
.nx-sup-hero { isolation: isolate; }
.nx-sup-hero-wash {
  z-index: -1;
  background:
    radial-gradient(60% 90% at 78% 40%, color-mix(in srgb, var(--color-violet) 22%, transparent), transparent 70%),
    radial-gradient(45% 70% at 98% 100%, color-mix(in srgb, var(--color-magenta) 12%, transparent), transparent 70%),
    radial-gradient(50% 80% at 0% 0%, color-mix(in srgb, var(--color-blue) 14%, transparent), transparent 70%);
}
html[data-theme="light"] .nx-sup-hero-wash { opacity: .55; }

.nx-sup-eyebrow {
  display: inline-flex; align-items: center; gap: 8px; align-self: flex-start;
  font-size: 12px; font-weight: 800; letter-spacing: .2em; text-transform: uppercase;
  color: var(--color-cyan);
}
.nx-sup-grad {
  background: linear-gradient(96deg, var(--color-blue), var(--color-violet) 55%, var(--color-magenta));
  -webkit-background-clip: text; background-clip: text; color: transparent;
}

.nx-sup-search {
  display: flex; align-items: center; gap: 10px; height: 50px; padding: 0 8px 0 16px;
  border-radius: 14px; border: 1px solid var(--color-rim-hi);
  background: color-mix(in srgb, var(--color-well) 88%, transparent);
  color: var(--color-tx-dim);
  transition: border-color .16s ease, box-shadow .16s ease;
}
.nx-sup-search:focus-within {
  border-color: color-mix(in srgb, var(--color-blue) 70%, var(--color-rim-hi));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--color-blue) 22%, transparent);
}
.nx-sup-results {
  border-radius: 14px; border: 1px solid var(--color-rim-hi);
  background: var(--color-surface);
  box-shadow: 0 18px 40px -12px rgba(0, 4, 16, .55);
}
html[data-theme="light"] .nx-sup-results { box-shadow: 0 18px 40px -16px rgba(20, 40, 80, .25); }

/* the one live/neon mark: assistant availability */
.nx-sup-live {
  position: relative; display: inline-block; width: 8px; height: 8px; flex: none;
  border-radius: 999px; background: var(--color-mint);
  box-shadow: 0 0 8px 1px color-mix(in srgb, var(--color-mint) 60%, transparent);
}
.nx-sup-live::after {
  content: ""; position: absolute; inset: 0; border-radius: inherit; background: var(--color-mint);
  animation: nx-sup-ping 2.2s cubic-bezier(0, 0, .2, 1) infinite;
}
@keyframes nx-sup-ping { 0% { opacity: .55; transform: scale(1); } 80%, 100% { opacity: 0; transform: scale(2.6); } }

.nx-sup-metrics { border-top: 1px solid var(--color-rim-soft); }
.nx-sup-metric {
  display: flex; flex-direction: column-reverse; gap: 7px; padding: 14px 20px;
  border-left: 1px solid var(--color-rim-soft);
}
.nx-sup-metric:nth-child(odd) { border-left: 0; }
@media (min-width: 640px) {
  .nx-sup-metric { padding: 16px 32px; }
  .nx-sup-metric:nth-child(odd) { border-left: 1px solid var(--color-rim-soft); }
  .nx-sup-metric:first-child { border-left: 0; }
}
@media (max-width: 639px) { .nx-sup-metric:nth-child(n+3) { border-top: 1px solid var(--color-rim-soft); } }
.nx-sup-metric dt::before {
  content: ""; display: inline-block; width: 10px; height: 3px; margin-right: 7px; vertical-align: middle;
  border-radius: 2px; background: var(--t);
}

/* ── channel cards ── */
.nx-sup-channel { position: relative; overflow: hidden; min-height: 168px; }
.nx-sup-channel::before {
  content: ""; position: absolute; left: 16px; right: 16px; top: 0; height: 2px; border-radius: 0 0 2px 2px;
  background: linear-gradient(90deg, var(--t), transparent);
  opacity: .7; transition: opacity .2s ease;
}
.nx-sup-channel:hover::before { opacity: 1; }
.nx-sup-channel-ico {
  border-radius: 12px; color: var(--t);
  background: linear-gradient(160deg, color-mix(in srgb, var(--t) 24%, transparent), color-mix(in srgb, var(--t) 6%, transparent));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--t) 38%, transparent);
}
.nx-sup-channel:focus-visible { outline: 2px solid var(--color-blue); outline-offset: 2px; }

/* ── tabs / chips ── */
.nx-sup-tabs, .nx-sup-chips { scrollbar-width: none; }
.nx-sup-tabs::-webkit-scrollbar, .nx-sup-chips::-webkit-scrollbar { display: none; }
.nx-sup-badge {
  display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 5px;
  border-radius: 999px; font-size: 11px; font-weight: 800; line-height: 1;
  color: var(--color-cyan);
  background: color-mix(in srgb, var(--color-cyan) 16%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--color-cyan) 40%, transparent);
}

.nx-sup-chip {
  display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 12px;
  border-radius: 999px; border: 1px solid var(--color-rim-hi);
  font-size: 12.5px; font-weight: 700; color: var(--color-tx-dim);
  background: transparent; transition: color .15s ease, border-color .15s ease, background .15s ease;
}
.nx-sup-chip:hover { color: var(--color-tx); border-color: color-mix(in srgb, var(--color-blue) 50%, var(--color-rim-hi)); }
.nx-sup-chip-n {
  font-size: 11px; font-weight: 800; color: var(--color-tx-faint);
  font-variant-numeric: tabular-nums;
}
.nx-sup-chip-on {
  color: var(--color-tx);
  border-color: color-mix(in srgb, var(--color-violet) 60%, transparent);
  background: linear-gradient(100deg, color-mix(in srgb, var(--color-blue) 18%, transparent), color-mix(in srgb, var(--color-violet) 18%, transparent));
}
.nx-sup-chip-on .nx-sup-chip-n { color: var(--color-tx-mute); }

/* ── ticket rows: a status filament on the left edge, like every live object ── */
.nx-sup-row { position: relative; transition: background .15s ease; }
.nx-sup-row::before {
  content: ""; position: absolute; left: 0; top: 14px; bottom: 14px; width: 3px; border-radius: 0 3px 3px 0;
  background: var(--e, var(--color-rim-hi));
}
.nx-sup-row[data-edge="amber"] { --e: var(--color-amber); }
.nx-sup-row[data-edge="cyan"] { --e: var(--color-cyan); }
.nx-sup-row[data-edge="blue"] { --e: var(--color-blue); }
.nx-sup-row[data-edge="rim"] { --e: var(--color-rim-hi); }
.nx-sup-row[data-edge="cyan"]::before { box-shadow: 0 0 10px 0 color-mix(in srgb, var(--color-cyan) 60%, transparent); }
.nx-sup-row:hover { background: color-mix(in srgb, var(--color-blue) 6%, transparent); }
.nx-sup-row:focus-visible { outline: 2px solid var(--color-blue); outline-offset: -2px; }

/* ── small icon plates ── */
.nx-sup-plate {
  place-items: center; border-radius: 10px; color: var(--color-blue);
  background: linear-gradient(160deg, color-mix(in srgb, var(--color-blue) 20%, transparent), color-mix(in srgb, var(--color-violet) 10%, transparent));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--color-blue) 30%, transparent);
}
.nx-sup-plate-warm {
  color: var(--color-amber);
  background: linear-gradient(160deg, color-mix(in srgb, var(--color-amber) 20%, transparent), color-mix(in srgb, var(--color-magenta) 10%, transparent));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--color-amber) 34%, transparent);
}
.nx-sup-urgent {
  background-image: linear-gradient(135deg, color-mix(in srgb, var(--color-amber) 7%, transparent), transparent 60%);
}
.nx-sup-overall { background: color-mix(in srgb, var(--color-mint) 9%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--color-mint) 28%, transparent); }
.nx-sup-overall[data-state="degraded"] { background: color-mix(in srgb, var(--color-amber) 10%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--color-amber) 30%, transparent); }
.nx-sup-overall[data-state="down"] { background: color-mix(in srgb, var(--color-rose) 10%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--color-rose) 30%, transparent); }

/* ── thread ── */
.nx-sup-avatar {
  color: var(--color-tx-dim); background: var(--color-well);
  box-shadow: inset 0 0 0 1px var(--color-rim-hi);
}
.nx-sup-avatar-staff {
  color: #fff; background: linear-gradient(140deg, var(--color-blue), var(--color-violet));
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--color-violet) 25%, transparent);
}
.nx-sup-staffpill {
  display: inline-flex; align-items: center; height: 17px; padding: 0 7px; border-radius: 999px;
  font-size: 10.5px; font-weight: 800; letter-spacing: .02em;
  color: var(--color-violet);
  background: color-mix(in srgb, var(--color-violet) 14%, transparent);
}
.nx-sup-meta {
  display: inline-flex; align-items: center; gap: 5px; height: 22px; padding: 0 9px; border-radius: 999px;
  font-size: 11.5px; font-weight: 600; color: var(--color-tx-mute);
  border: 1px solid var(--color-rim-hi); background: var(--color-well);
}
.nx-sup-bubble { border-radius: 16px; padding: 12px 16px; }
.nx-sup-bubble-staff {
  border-top-left-radius: 5px;
  background: var(--color-well); border: 1px solid var(--color-rim-hi);
}
.nx-sup-bubble-me {
  border-top-right-radius: 5px;
  background: linear-gradient(140deg, color-mix(in srgb, var(--color-blue) 24%, var(--color-surface)), color-mix(in srgb, var(--color-violet) 22%, var(--color-surface)));
  border: 1px solid color-mix(in srgb, var(--color-violet) 35%, transparent);
}
html[data-theme="light"] .nx-sup-bubble-me {
  background: linear-gradient(140deg, color-mix(in srgb, var(--color-blue) 10%, #fff), color-mix(in srgb, var(--color-violet) 9%, #fff));
}

/* ── New ticket dialog (components/customer/TicketForms.tsx) ── */
.nx-sup-choice {
  border-radius: 12px; border: 1px solid var(--color-rim-hi);
  background: color-mix(in srgb, var(--color-well) 70%, transparent);
  transition: border-color .15s ease, background .15s ease, box-shadow .15s ease;
}
