  border-color: color-mix(in srgb, var(--color-violet) 70%, transparent);
  background: linear-gradient(140deg, color-mix(in srgb, var(--color-blue) 14%, transparent), color-mix(in srgb, var(--color-violet) 16%, transparent));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--color-violet) 45%, transparent), 0 8px 24px -14px var(--color-violet);
}
.nx-sup-choice-on .nx-sup-choice-ico { color: #fff; background: linear-gradient(140deg, var(--color-blue), var(--color-violet)); }

.nx-sup-seg {
  padding: 3px; gap: 3px; border-radius: 12px; border: 1px solid var(--color-rim-hi);
  background: var(--color-well);
}
.nx-sup-seg-opt {
  display: grid; place-items: center; height: 36px; border-radius: 9px; cursor: pointer;
  font-size: 12.5px; font-weight: 700; color: var(--color-tx-dim);
  transition: color .15s ease, background .15s ease;
}
.nx-sup-seg-opt:hover { color: var(--color-tx); }
.nx-sup-seg-opt:focus-within { outline: 2px solid var(--color-blue); outline-offset: 1px; }
.nx-sup-seg-on { color: var(--color-tx); background: var(--color-surface); box-shadow: 0 1px 0 0 var(--color-rim-hi), 0 0 0 1px var(--color-rim-hi); }
.nx-sup-seg-on[data-prio="HIGH"] { color: var(--color-amber); }
.nx-sup-seg-on[data-prio="URGENT"] { color: var(--color-rose); box-shadow: 0 0 0 1px color-mix(in srgb, var(--color-rose) 50%, transparent); }

.nx-sup-suggest {
  border: 1px solid color-mix(in srgb, var(--color-violet) 35%, transparent);
  background: linear-gradient(140deg, color-mix(in srgb, var(--color-violet) 9%, transparent), color-mix(in srgb, var(--color-blue) 6%, transparent));
}
