/* eslint-disable @next/next/no-img-element -- third-party brand assets, fixed size */

/**
 * Third-party company marks, for the Integrations panel.
 *
 * Cloudflare and Anthropic already live in `public/logos/` (the same files the
 * app catalogue and Build with AI use), so those are served from disk. Discord
 * has no asset in the tree, so its mark is drawn inline from the official
 * geometry rather than adding a fetched image — one less binary to keep in step
 * with a brand refresh, and it takes `currentColor` so it reads correctly on
 * both the connected and disconnected states.
 */

export type BrandId = "cloudflare" | "anthropic" | "discord";

function DiscordMark({ size }: { size: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 127.14 96.36" fill="currentColor" aria-hidden>
      <path d="M107.7,8.07A105.15,105.15,0,0,0,81.47,0a72.06,72.06,0,0,0-3.36,6.83A97.68,97.68,0,0,0,49,6.83,72.37,72.37,0,0,0,45.64,0,105.89,105.89,0,0,0,19.39,8.09C2.79,32.65-1.71,56.6.54,80.21h0A105.73,105.73,0,0,0,32.71,96.36,77.7,77.7,0,0,0,39.6,85.25a68.42,68.42,0,0,1-10.85-5.18c.91-.66,1.8-1.34,2.66-2a75.57,75.57,0,0,0,64.32,0c.87.71,1.76,1.39,2.66,2a68.68,68.68,0,0,1-10.87,5.19,77,77,0,0,0,6.89,11.1A105.25,105.25,0,0,0,126.6,80.22h0C129.24,52.84,122.09,29.11,107.7,8.07ZM42.45,65.69C36.18,65.69,31,60,31,53s5-12.74,11.43-12.74S54,46,53.89,53,48.84,65.69,42.45,65.69Zm42.24,0C78.41,65.69,73.25,60,73.25,53s5-12.74,11.44-12.74S96.23,46,96.12,53,91.08,65.69,84.69,65.69Z" />
    </svg>
  );
}

export function BrandMark({ id, size = 26 }: { id: BrandId; size?: number }) {
  if (id === "discord") return <DiscordMark size={size} />;
  const src = id === "cloudflare" ? "/logos/cloudflare.png" : "/logos/claude.png";
  return (
    <img
      src={src}
      alt=""
      height={size}
      style={{ height: size, width: "auto", maxWidth: size + 8 }}
      className="select-none object-contain"
      aria-hidden
    />
  );
}
